param(
    [string]$DocsRoot = 'docs/NPSPEC/Boot',
    [string]$OutputFile = 'build/bootmanager-npspec-coverage.md'
)

$ErrorActionPreference = 'Stop'
$root = (Resolve-Path -LiteralPath $DocsRoot).Path
$files = Get-ChildItem -LiteralPath $root -Recurse -File -Filter '*.md' | Sort-Object FullName

$evidenceRules = @(
    @{ Pattern = 'NPSPEC-BOOTCONTROL-LISTITEM-0001'; Status = 'Teilweise integriert'; Evidence = 'controls.c/ui.c/main.c: heapfreies typisiertes ListItem mit Titel, Subtitle, Status, stabiler ID/Reihenfolge, Normal/Hover/Focus/Selected/Disabled/Pressed/Error, Theme-Rundung, eindeutiger Auswahlmarkierung, Icon-/Label-Komposition und Accessibility; Haupt-, Settings-, Diagnose-, Power-, Firmware- und Hilfelisten nutzen es produktiv mit Maus, Tastatur, Space und Kontextmenü; Touch/Doppelklick, Item-Motion und BIOS-Anbindung fehlen' },
    @{ Pattern = 'NPSPEC-BOOTCONTROL-LIST-0001'; Status = 'Teilweise integriert'; Evidence = 'controls.c/ui.c/main.c: feste indexierbare 64er Item-Collection im 128er Control-Pool mit stabiler Reihenfolge, Add/Remove, None/Single/Multi, O(1)-Direktauswahl, Fokus, sichtbarem Virtualisierungsfenster und ScrollView-Kopplung; produktive Bootmanager-Listen unterstützen Pfeile, Home/End, Page Up/Down, Enter/Space, Maus und QEMU-Nachweis; Touch/Controller, sehr große Providerlisten, Insert/Remove-Motion und BIOS-Anbindung fehlen' },
    @{ Pattern = 'NPSPEC-BOOTCONTROL-LABEL-0001'; Status = 'Teilweise integriert'; Evidence = 'controls.c/ui.c/text.c: heapfreies Label-Control mit neun Typen, neun horizontal/vertikal kombinierten Ausrichtungen, Ein-/Mehrzeile, Wrap/Ellipsis, dynamischem UTF-8-Text, Theme-/Statusfarben und DPI-Skalierung; Wortmarke und Statuszeile nutzen es produktiv, Host- und QEMU-Nachweise vorhanden; relationale Beschriftung, Motion und BIOS-Anbindung fehlen' },
    @{ Pattern = 'NPSPEC-BOOTCONTROL-ICON-0001'; Status = 'Teilweise integriert'; Evidence = 'controls.c/icons.c/ui.c: heapfreies semantisches Icon-Control mit validierten zentralen Token-Ressourcen, proportionaler DLU-Skalierung, Theme-/Disabled-/Statusfarben und dekorativ/semantischer Accessibility; alle sechs sichtbaren Menü-/Tile-Icons nutzen es produktiv, Host- und QEMU-Nachweis vorhanden; allgemeiner SVG-Primärpfad, Motion und BIOS-Anbindung fehlen' },
    @{ Pattern = 'NPSPEC-BOOTCONTROL-IMAGE-0001'; Status = 'Teilweise integriert'; Evidence = 'controls.c/branding.c/resources.c/ui.c: heapfreies Image-Control mit Original/Stretch/Fit/Fill/Center, Clipping, Alpha-Coverage, Tint und zentral wiederverwendeter validierter NovaOS-Logo-Ressource; das Branding nutzt produktiv Fit und Theme-Tint, Host- und QEMU-Nachweis vorhanden; weitere PNG/BMP/QOI/SVG-Decoder bleiben durch fehlendes BAP-/Index-Wire-Format blockiert, Motion und BIOS-Anbindung fehlen' },
    @{ Pattern = 'NPSPEC-BOOTCONTROL-SEPARATOR-0001'; Status = 'Teilweise integriert'; Evidence = 'controls.c/ui.c: nicht-interaktives heapfreies Separator-Control mit horizontaler/vertikaler Ausrichtung, optionalem zentriertem Titel, Theme-Linie und dekorativer Accessibility; die Settings-Gruppen werden produktiv horizontal getrennt, Host- und QEMU-Framebuffer-Nachweis vorhanden; Icon-Variante, Theme-Fade und BIOS-Anbindung fehlen' },
    @{ Pattern = 'NPSPEC-BOOTCONTROL-BUTTON-0001'; Status = 'Teilweise integriert'; Evidence = 'controls.c/ui.c/dialog.c: heapfreies Button-Control mit sieben validierten Typen, Text/Icon, Aktion, Pressed-/Toggle-/Busy-Schutz, exakt-einmal-Auslösung, Theme, Rundung, Fokus und Accessibility; Dialogaktionen verwenden produktiv Primary/Secondary/Destructive Buttons, Host- und QEMU-Dialogtests sind grün; Touch/Controller, vollständige Motion und gemeinsame BIOS-Anbindung fehlen' },
    @{ Pattern = 'NPSPEC-BOOTCONTROL-MENUBUTTON-0001'; Status = 'Teilweise integriert'; Evidence = 'controls.c/ui.c/main.c: heapfreier Menu Button mit validierter 1:1-Menübindung, Collapsed/Expanded, Pfeilindikator, Safe-Area-Overlay und Fokus-Rückgabe; die Theme-Auswahl verwendet ihn produktiv mit Maus, Enter/Space, Pfeilen, Home/End, Escape/Links und drei Theme-Aktionen; Hosttests sowie QEMU-Marker/Framebuffer-Nachweis vorhanden; Touch/Controller, Arrow-Motion, Untermenüs und BIOS-Anbindung fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-0002'; Status = 'Teilweise integriert'; Evidence = 'resources.c: BAP-1-Wire-Header wird little-endian, größen- und alignmentfest geprüft; unbekannte Flags, Bereichsüberlappungen, Paket-CRC, Index-CRC, Ressourcenanzahl, Datenbereiche, Ressourcendaten-CRC und überlappende Payloads werden vor Nutzung abgewiesen. Hosttests erzeugen ein echtes gültiges Paket im Speicher. Dateisystem-Open/Close, Manifestauswertung, optionale Signatur und atomare Registrierung aller Paketressourcen fehlen noch' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-0003'; Status = 'Teilweise integriert'; Evidence = 'resources.c: normativer 40-Byte-NOVAIDX-Header und 64-Byte-Einträge, Power-of-two-Hash-Tabelle, 70-Prozent-Grenze, FNV-ID-Schlüssel, lineares Open Addressing, eindeutige IDs/Slots, Typ/Version/Kompression/Größen sowie Dependency-Bereiche werden heapfrei validiert. Hosttests decken gültigen Index und fehlenden Hash-Eintrag ab. Ein Paket-Descriptor-Adapter und produktives Lazy Loading direkt aus dem Paket fehlen noch' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-0001'; Status = 'Teilweise integriert'; Evidence = 'resources.c: zentraler heapfreier Manager mit 128er Objektpool und 256er Open-Addressing-Hashindex für O(1)-URI/ID-Lookup. Modell und Lifecycle enthalten unveränderlichen Namen/ID, Typ, Version, Größe, CRC32, Herkunft, Zustand, Adresse, Referenzen, Fallback, Priorität und bis zu acht Abhängigkeiten. Lazy/Preload, CRC vor Registrierung und jeder Nutzung, Cache-Hit/Miss, transitive Referenzen, Zyklenschutz, 8-MiB-Budget/LRU-Eviction, Unload und Shutdown sind typisiert. Font, Icons, Themes, Design und Logo werden zentral registriert und vor dem ersten UI-Frame verifiziert/preloaded. Hosttests belegen Abhängigkeit, Zyklus, beschädigte Primärressource mit Fallback, LRU, Busy-Unload, Background-Abweisung, Preload und Shutdown. OVMF/QEMU meldet RESOURCE-LOADER-READY und RESOURCE-PRELOAD-READY. Externe Packages, Signaturen und Paketstruktur bleiben durch die fehlenden Wire-Formate in 0002/0003 blockiert; echte Ladezeitmessung, persistente Packageherkunft und BIOS-C-Pipeline-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-0004'; Status = 'Teilweise integriert'; Evidence = 'resources.c/ui.c: typisierter Resource Loader mit Lazy und synchronem Preload, Prioritätsreihenfolge Critical/High/Normal/Low, O(1)-Index/Cache, fester Registry ohne Hotpath-Allokation, CRC-/Typ-/Version-/Größenprüfung, mehrfacher Ladeunterdrückung, Referenzzählung, automatischer transitiver Abhängigkeitsauflösung, Zyklusdetektion, Default-Fallback, Budget/LRU und deterministischem Unload. Optionales Background Loading wird explizit UNSUPPORTED statt scheinimplementiert. Produktiv werden alle eingebetteten GUI-Assets bis Normal vor Verwendung verifiziert; QEMU bootet damit alle Menüframes. Package Reader, Indexdescriptor-/Offsetprüfung und Dekompression aus externen BAPs können ohne 0002/0003-Wire-Format nicht implementiert werden; echte parallele Anfragen, asynchrones Background Loading, Loader-Dispatcher pro Packageformat, Lade-/Dekompressionszeitmessung und gemeinsame BIOS-Anbindung fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-0005'; Status = 'Teilweise integriert'; Evidence = 'compression.c/resources.c/ui.c: transparenter heapfreier Resolver für NONE und verpflichtendes LZ4-Raw-Blockformat mit O(n)-Decoder, vollständigen Längen-/Offset-/Grenz-/Überlaufprüfungen, überlappenden Matches, exakter Ausgabegröße und typisierten Fehlern; optionales Zstd wird explizit UNSUPPORTED gemeldet. Der Resource Loader prüft CRC32 der gepackten Daten vor, entpackt beim ersten Zugriff in einen statischen 512-KiB-Blockpool, prüft Größe und CRC32 danach, cached genau eine dekodierte Kopie und evicted prioritäts-/LRU-basiert unter Pooldruck. Fehler aktivieren verifizierte Fallbacks. Diagnosen erfassen Verfahren, Größen, Verhältnis, Aufrufe, Dekompressionen, Fehler und Poolverbrauch. Hosttests belegen NONE, LZ4-Literal/Match/Overlap, beschädigten/trunkierten Stream, Größenfehler, Zstd-Abweisung, Lazy Loading, Cache-Wiederverwendung, Fallback und Poolgrenze. OVMF/QEMU dekodiert beim realen Start eine gepackte Probe und meldet RESOURCE-LZ4-DECODE-READY. Externe BAP-/Indexanbindung bleibt mangels normativem Wire-Format in 0002/0003 blockiert; Zstd, Zeitmessung, größere Ressourcen als der statische Pool und gemeinsame BIOS-C-Pipeline fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-0006'; Status = 'Teilweise integriert'; Evidence = 'integrity.c/resources.c/ui.c: heapfreier Integritätsmanager mit CRC32, vollständigem SHA-256, konstantzeitlichem Digestvergleich, Trust Unknown/Valid/Signed/Invalid/Corrupted und Richtlinien Permissive/Standard/Strict. Headerähnliche Metadaten werden auf ID, Typkontext, Version, Datenzeiger, Größe, Pointerüberlauf und Signaturstatus geprüft. Der Loader validiert gepackte Daten vor Dekompression sowie Originalgröße, CRC32 und optional SHA-256 danach, speichert Trust O(1) an der Ressource und überspringt erneutes Hashing nur bei weiterhin gecachten validierten Daten. Ungültige Daten/Signaturzustände werden verworfen und nutzen den typisierten Fallback; Abhängigkeiten und Zyklen prüft der Loader transitiv. Hosttests belegen FIPS-SHA-256-abc, CRC/SHA, alle drei Richtlinien, ungültige und vorgelagert verifizierte Signaturzustände, Korruption, Fallback und Cache-Skip. OVMF/QEMU prüft feste SHA-256-Werte einer gepackten und dekodierten LZ4-Ressource und meldet RESOURCE-SHA256-VERIFIED. Kryptografische Ed25519/ECDSA-Verifikation, Schlüssel-/Signatur-Wire-Format, Paket-/Indexheader und Manifestauthentizität sind ohne BOOTSECURITY-0001 sowie normative 0002/0003-Formate nicht implementierbar; SHA-512, Zeitmessung und BIOS-C-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-0007'; Status = 'Teilweise integriert'; Evidence = 'image_renderer.c/resources.c/ui.c: plattformneutraler heapfreier PNG-1.2-Decoder mit öffentlicher Initialize/Validate/Decode-API, statischem 240-KiB-Decodepuffer und 512-KiB-RGBA-Pixelpool. Unterstützt werden verpflichtend Grayscale, RGB, RGBA und Indexed in 1/2/4/8 Bit sowie optional Grayscale+Alpha 8 Bit; Ausgabe ist premultipliziertes RGBA32. PLTE und tRNS für Palette, Grayscale und RGB, mehrere zusammenhängende IDAT-Chunks, Stored/Fixed/Dynamic Deflate, Adler32 und alle Filter None/Sub/Up/Average/Paeth sind implementiert. Parser prüft Signatur, IHDR-first, Chunknamen/Reserved Bit, Längen/Überläufe, CRC jedes Chunks, PLTE/tRNS/IDAT/IEND-Reihenfolge, unbekannte Critical Chunks, exaktes IEND und Dimensionen vor Allokation. Hosttests belegen sämtliche Farbtypen, Packed 1/2 Bit, Alpha/tRNS, Multi-IDAT, alle fünf Filter, Deflatevarianten, CRC-Schaden, Interlace-Abweisung und Validierungsdiagnose. OVMF/QEMU lädt und prüft eine echte 1-Bit-Grayscale/tRNS-PNG-Ressource und meldet PNG-DECODER-READY. Optionales 16 Bit und Adam7, unbegrenzt viele IDATs, Decodezeitmessung, externer BAP-Pfad und gemeinsame BIOS-C-Pipeline fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-0008'; Status = 'Teilweise integriert'; Evidence = 'svg_renderer.c/vector_geometry.c: heapfreier, größenbegrenzter XML-/SVG-Parser mit strikter Element- und Attribut-Whitelist, Verbot von DTD/Processing Instructions/unbekannten Elementen, maximal 64 Elementen sowie absolutem und relativem M/L/H/V/Q/C/Z-Path-Parsing. #RRGGBB, #RRGGBBAA, none, drei Nova-Themefarben, Nonzero/Evenodd, Vierfach-AA und premultipliziertes Source-over sind hostgetestet und freestanding in BOOTX64.EFI gelinkt. Rect/Circle/Ellipse/Line/Polyline/Polygon, ViewBox-Skalierung, Transformstack, Stroke-Geometrie, Cache und produktive Icon-Anbindung fehlen noch' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-0009'; Status = 'Teilweise integriert'; Evidence = 'font_resources.c/text.c/resources.c/ui.c: zentrale heapfreie 16er Font-Registry mit 32er Open-Addressing-ID-Index, validierten unveränderlichen Metadaten für ID, Ressourcen-ID/Version, Name, Familie, Stil, Gewicht, Priorität, sortierter Unicode-Abdeckung und Fallback-ID. Laden erfolgt ausschließlich über den Resource Loader; Registry/Resource-Referenzen, Cache-Hits und Duplicate-Schutz sind typisiert. Der deterministische Resolver verarbeitet Primary -> font-eigener Fallback -> Theme-Fallback -> Systemfont -> Missing Glyph mit Zyklenschutz. Fünf Theme-Rollen wechseln nur IDs ohne Fontneuladung. Die Textengine fragt die Registry vor jeder Glyphe ab; die bestehende 2-Bit-AA-Systemschrift ist als UI/SemiBold mit tatsächlicher ASCII-/Umlautabdeckung registriert. Hosttests belegen Metadaten, O(1)-Lookup, Load/Release/Cache, Abdeckung, Missing Glyph, zweite Symbolschrift, Fallback, Theme-Rolle und Duplicate-Abweisung. OVMF/QEMU lädt die Systemschrift produktiv und meldet FONT-RESOURCE-REGISTRY-READY. Das verpflichtende Nova Font Package ist nicht parsbar, weil keine NFP-Magic, Headerpackung, Endianness, Tabellenoffsets, Mapping-/Metrik-/Kerningformate oder Signaturbereiche definiert sind; externe BAPs, vollständige Unicodefonts, sprach-/scriptbasierte Priorisierung, TTF/OTF und BIOS-C-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-0010'; Status = 'Teilweise integriert'; Evidence = 'animation_resources.c/motion.c/resources.c/ui.c: zentrale heapfreie 32er Animationsregistry mit 64er Open-Addressing-ID-Index und festen 32 Keyframes je Ressource. Deskriptor und Validator decken ID/Name/Version, Ressourcenversion, Dauer, Once/Count/Infinite, Trigger, Kategorie, Priorität, Property, Easing und pro Property strikt sortierte Start-/End-Keyframes ab. Loader/Referenzen/Cache und Duplicate-Schutz nutzen ausschließlich Resource Manager. Der O(n)-Timeline-Resolver interpoliert kombinierte Properties deterministisch mit der Motion-Easing-Engine, behandelt Wiederholungen/Endzustand, Theme-Speed 25-400 Prozent und Reduced Motion. Triggerauflösung ist priorisiert O(n), ID-/Theme-Slot-Lookup O(1). Hosttests belegen kombinierte Opacity/Scale-Keyframes, Easing, Wiederholung, Speed, Trigger, Themebindung, Cache, Duplicate, ungültige Timeline und Reduced Motion. OVMF/QEMU lädt eine echte deklarative Page-Enter-Ressource, bindet sie ans Theme, sampelt sie und meldet ANIMATION-RESOURCE-READY. Mehrere bestehende spezialisierte Dialog-/Fokus-/Progress-Helfer besitzen noch hartkodierte Defaultwerte statt ausschließlich Ressourcendeskriptoren; externes Animations-Wire-Format, Color-Keyframeformat, sprachliche Triggerpayloads, Zeitmessung und BIOS-C-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTTEXT-0003'; Status = 'Teilweise integriert'; Evidence = 'unicode.c/text.c: validierender UTF-8-Decoder bis U+10FFFF, Overlong-/Surrogat-Abweisung, U+FFFD-Missing-Glyph, UTF-8-Umlaute, Block-/Fehlertests und Diagnose; internationale Glyphatlanten fehlen' },
    @{ Pattern = 'NPSPEC-BOOTDESIGN-0009'; Status = 'Teilweise integriert'; Evidence = 'icons.c/ui.c: alle 15 semantischen O(1)-Tokens besitzen zentral registrierte, geprüfte 2-Bit-AA-Ressourcen; Unterseiten verwenden eigene Tokenzuordnungen, DLU-Skalierung, Theme-Tint, Cache-Diagnose und ausschließlich einen Fallback für ungültige externe Tokens; allgemeiner SVG-Renderer und BIOS-Parität der neun erweiterten Symbole fehlen' },
    @{ Pattern = 'NPSPEC-BOOTDESIGN-0002'; Status = 'Teilweise integriert'; Evidence = 'theme.c: validierte statische O(1)-Token-Tabellen für Farben, Abstände, Radien, Transparenz, Material und Motion-Overrides; Typography-/Shadow-Registry noch nicht vollständig' },
    @{ Pattern = 'NPSPEC-BOOTDESIGN-0003'; Status = 'Teilweise integriert'; Evidence = 'theme.c/ui.c: sämtliche UEFI-Farben über semantische Rollen, deterministischer Kontrasttest, Focus/Selected/Disabled/Statusfarben und Accessibility-Overrides; BIOS nutzt weiterhin eigene äquivalente Tokenquelle' },
    @{ Pattern = 'NPSPEC-BOOTDESIGN-0004'; Status = 'Teilweise integriert'; Evidence = 'design.c/design.h/font_resources.c/ui.c: heapfreie, pro Theme vorbereitete O(1)-Typography-Registry mit allen elf Pflichtrollen Display, Headline, Title, Subtitle, Body, Body.Small, Caption, Button, Menu, Status und Monospace. Jede Rolle führt Font-ID, Größe, minimale/standard/maximale Zeilenhöhe, echten Weight, semantisches Tracking und festen Letter-Spacing-Wert; Validator erzwingt Font, Größen- und Zeilenhöheninvarianten. Dark/Light und ein vergrößertes High-Contrast-/Accessibility-Profil wechseln ohne Control-Neuerzeugung. Font-ID bindet an die zentrale validierte Font Registry/Fallbackkette. Hosttests prüfen Vollständigkeit, O(1)-Lookup, Invarianten und Themewechsel; OVMF/QEMU meldet SEMANTIC-DESIGN-TOKENS-READY. Die produktive Textengine nutzt Font Resources und skalierte Rollen, aber noch nicht jeder ältere Zeichenaufruf wurde von einem lokalen Scale-Wert auf eine explizite Rollen-ID migriert; vollständige Unicodefonts und BIOS-Pixelparität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTDESIGN-0005'; Status = 'Teilweise integriert'; Evidence = 'design.c/design.h/ui.c/layout.c: heapfreie O(1)-Registry mit allen acht semantischen DLU-Tokens XXS bis XXXL, monotoner Validierung und vorbereiteten Dark-/Light-/High-Contrast-Accessibilityprofilen. Zentrale Control-Styles beziehen Padding und Badgeabstände produktiv über den Resolver; die responsive Layoutengine skaliert DLU und Safe-Area/Breakpoints weiter deterministisch. Hosttests prüfen Existenz, Reihenfolge und profilabhängige Werte, der reale UEFI-Pfad validiert sie vor dem ersten Frame und meldet SEMANTIC-DESIGN-TOKENS-READY. Einige ältere spezialisierte Renderer enthalten noch lokale DLU-Abstände statt ausschließlich Token-IDs; Touchprofil und vollständige BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTDESIGN-0006'; Status = 'Teilweise integriert'; Evidence = 'design.c/design.h/ui.c/rounded_geometry.c: heapfreie O(1)-Registry mit allen acht Rollen None, Tiny, Small, Medium, Large, XLarge, Pill und Circle. Dark/Light sowie vereinfachtes High Contrast werden pro Theme vorbereitet und validiert; zentrale Control-, Listen-, Badge- und Panelstyles lösen Radien produktiv semantisch auf. Der Rounded-Geometry-Renderer liefert AA, Clipping/Maskierung und animierbare Radiusgeometrie. Hosttests prüfen Vollständigkeit und Themewerte; OVMF/QEMU validiert die Registry und meldet SEMANTIC-DESIGN-TOKENS-READY. Einige spezialisierte Renderer speichern noch direkte DLU-Radien, dynamische Pill/Circle-Auflösung ist renderergeklemmt und vollständige BIOS-Parität fehlt' },
    @{ Pattern = 'NPSPEC-BOOTDESIGN-0007'; Status = 'Teilweise integriert'; Evidence = 'design.c/design.h/effects.c/ui.c: heapfreie O(1)-Registry für None und Elevation Level1 bis Level5 mit genau zugeordneten ein- oder zweilagigen Shadow Tokens. Jede Lage führt DLU-X/Y, nichtnegativen Blur, Alpha und Farbe; Dark/Light besitzen abgestufte Hierarchien, High Contrast deaktiviert Tiefeneffekte semantisch. Der produktive Dialogrenderer bezieht beide Shadow-Layer und X/Y/Blur/Opacity/Farbe ausschließlich aus Level4, skaliert DLU und rendert über den Software-Shadow-Renderer; Elevation beeinflusst nicht die Input-Z-Reihenfolge. Hosttests prüfen alle Ebenen und Accessibility, OVMF/QEMU meldet EFFECT-MOTION-TOKENS-READY. Andere spezialisierte Oberflächen verwenden teilweise noch direkte Effekte, Elevation-Morphing ist über Effect-Lerp/Motion möglich aber nicht an jedem Control gebunden, BIOS-Parität fehlt' },
    @{ Pattern = 'NPSPEC-BOOTDESIGN-0008'; Status = 'Teilweise integriert'; Evidence = 'design.c/design.h/background_blur.c/ui.c/compositor.c: heapfreie O(1)-Registry mit allen acht Rollen None, Surface, Glass, Glass.Light, Glass.Medium, Glass.Strong, Overlay und Dialog. Profile führen Surface-/Borderfarbe, DLU-Blur, Alpha, Reflexion, Helligkeit, Elevation und Opaque-Fallback; Parameter werden beim Designstart validiert. Dialog und Overlay beziehen Farbe, Rand, Blur und Transparenz produktiv aus Tokens und rendern über den cachefähigen Software-Blur-/Compositorpfad. High Contrast ersetzt alle Glasrollen durch opake Schwarz/Weiß-Flächen ohne Blur. Hosttests prüfen Vollständigkeit/Profile, OVMF/QEMU meldet EFFECT-MOTION-TOKENS-READY und bestehende Blur-Marker. Reflexion/Helligkeit werden gespeichert, aber noch nicht als eigene Renderpasses genutzt; einige Control-Materialarten sind noch generisch, BIOS-Parität fehlt' },
    @{ Pattern = 'NPSPEC-BOOTDESIGN-0010'; Status = 'Teilweise integriert'; Evidence = 'design.c/design.h/motion.c/ui.c: heapfreie O(1)-Registry mit Instant, UltraFast, Fast, Normal, Slow, VerySlow; acht Easingrollen Linear, EaseIn, EaseOut, EaseInOut, Decelerate, Accelerate, Spring, Overshoot; sowie Page, Dialog, Menu, Tooltip, Card, Focus und Selection. Jedes Übergangsprofil führt Dauer, Easing, Emphasis, Priorität und Disabled. Dialog Enter/Exit, Navigation, Fokus und Progress verwenden produktiv nur noch diese Resolver. Theme-/Reduced-Motion-Auflösung liefert 1-ms-Linearfallback ohne Rollenneubenennung. Validator prüft Vollständigkeit, Zeiten und Easing. Hosttests prüfen Kategorien, Profile und Accessibility, OVMF/QEMU meldet EFFECT-MOTION-TOKENS-READY. Page-Enter-Keyframes und einige ältere Spezialanimationen enthalten noch lokale Timelinezeiten; EaseIn/Accelerate werden mangels separater Kurve auf deterministisches EaseInOut abgebildet, BIOS-Parität fehlt' },
    @{ Pattern = 'NPSPEC-BOOTDESIGN-0011'; Status = 'Teilweise integriert'; Evidence = 'design.c/design.h/controls.c/controls.h/ui.c: zentrale heapfreie O(1)-Registry für alle zwölf Pflichtzustände Normal, Hover, Focused, Pressed, Selected, Checked, Expanded, Collapsed, Disabled, ReadOnly, Loading und Error. Jeder Zustand besitzt semantische Surface-/Text-/Borderfarben, Opacity, Elevation, Radius, Cursor, Motion, Eingabesperre und einen nicht-farbbasierten Fehlerindikator. Eine feste Übergangsmatrix validiert Zustandswechsel; Fokus hat Vorrang, Hover akzeptiert ausschließlich Pointerquellen, Disabled/ReadOnly/Loading unterscheiden ihre Eingaberegeln. Textfelder, ListItems, Tiles, IconButtons, Buttons und MenuButtons lösen sichtbare Farben, Radien und Fokus/Error-Zeichen produktiv über die Registry auf. Dark/Light/High Contrast und Reduced Motion werden ohne Control-Neuerzeugung neu gebunden. Hosttests prüfen Vollständigkeit, Übergänge und Sperrregeln; OVMF/QEMU meldet INTERACTION-STATES-READY. Cursorformen werden mangels spezifizierter Cursor-Assetbindung nur semantisch geführt, Zustandsanimationen verwenden vorhandene Motionprofile ohne vollständiges Per-Control-Tweening, Touch/Controller und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTDESIGN-0012'; Status = 'Teilweise integriert'; Evidence = 'theme.c/theme.h/design.c/ui.c: Dark ist eine statische, heapfreie und versionierte Default-Theme-Resource mit normativem Descriptor, is-dark-Abfrage und atomarer activate-default-API. Vor jeder Aktivierung werden alle 14 Farbrollen, Alpha, DLU-Geometrie, monotone Abstände sowie feste Mindestkontraste für Primär-/Sekundärtext, Fokus und Akzent geprüft; Loader validiert zusätzlich Typ, Version, Größe, Adresse und Resource-Checksumme. Sämtliche Typography-, Spacing-, Radius-, Shadow-, Material-, Motion-, Interaction-State- und Icon-Registries besitzen vorbereitete Dark-Profile und O(1)-Resolver. Reduced Motion und opake Materialfallbacks überschreiben semantisch, ohne Tokenrollen oder Controls auszutauschen. Hosttests prüfen Descriptor, Ressourcenreferenzen, Cache, Kontraste, Wechsel, Accessibility und ungültige IDs; ein frisch gebautes GPT/FAT32-Image meldet in EDK2/QEMU DARK-THEME-READY und zeichnet den Countdownframe. Der allgemeine externe Theme-Paketpfad bleibt durch fehlende normative BAP-/Index-Wire-Formate blockiert; mehrere ältere Spezialrenderer verwenden noch lokale DLU-Werte, SVG-Primäricons und vollständige BIOS-Pixelparität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTDESIGN-0013'; Status = 'Teilweise integriert'; Evidence = 'theme.c/theme.h/design.c/ui.c/main.c: Light ist eine statische, heapfreie, versionierte und nicht als Default markierte Theme-Resource mit vollständigem Descriptor, is-light-Abfrage und atomarer activate-light-API. Sie durchläuft dieselbe vollständige Farbrollen-, Alpha-, DLU- und Mindestkontrastvalidierung wie Dark sowie Loaderprüfungen auf Typ, Version, Größe, Adresse und Checksumme. Typography, Spacing, Radius, Shadow, Material, Motion, Interaction States und Icons werden über unveränderte semantische O(1)-Resolver neu gebunden; Controls bleiben beim Wechsel bestehen. Hosttests prüfen Descriptor, Ressourcenreferenz, Cache, Wechsel und ungültige IDs. Der marker-synchronisierte EDK2/QEMU-Test wechselt Dark -> Light -> High Contrast -> Dark, erzeugt einen 1024x768-Light-Framebuffer, öffnet das Theme-Menü und prüft Reduced Motion; das GPT/FAT32-Image meldet LIGHT-THEME-READY vor dem Countdownframe. Externe Theme-Pakete bleiben durch fehlende BAP-/Index-Wire-Formate blockiert; SVG-Primäricons und vollständige BIOS-Light-Pixelparität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTDESIGN-0014'; Status = 'Teilweise integriert'; Evidence = 'theme.c/theme.h/design.c/controls.c/ui.c: High Contrast besitzt einen eigenen statischen Accessibility-Descriptor, is-high-contrast-Abfrage und atomare Aktivierungs-API. Aktivierung verlangt vollständig opake Materialien und Overlays, Reduced Motion, mindestens 2 DLU Fokusgeometrie, 7:1-Kontrast für Primärtext/Fokus/Ebenentrennung sowie 4,5:1 für Success, Warning, Error und Information. Größere Typography-, Spacing- und Iconprofile, reduzierte Radien, deaktivierte Shadows/Blur, lineare 1-ms-Motion und nicht-farbbasierte Error-Symbol-/Textindikatoren werden über unveränderte semantische O(1)-Resolver angebunden. Hosttests prüfen Descriptor, Kontraste, Motion- und Materialfallback; der marker-synchronisierte EDK2/QEMU-Test erzeugt einen 1024x768-High-Contrast-Framebuffer, wechselt Themes und prüft Reduced Motion. Das GPT/FAT32-Image meldet HIGH-CONTRAST-THEME-READY. Ein Screenreader-/Sprachausgabebackend, alternative Farbschemata, SVG-Primäricons und vollständige BIOS-Pixelparität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTDESIGN-0015'; Status = 'Teilweise integriert'; Evidence = 'design.c/design.h/theme.c/controls.c/ui.c: der Bootbereich veröffentlicht einen heapfreien Visual-Continuity-Kontext mit NDL-Major-Version, aktiver Theme-Ressourcen-ID, Accessibility-Semantikerhalt und deterministischer FNV-Signatur über die gemeinsamen Typography-, Spacing-, Radius-, Icon-, Material-, Motion- und Interaction-State-Registries. Ein Moduldescriptor muss exakte Version, Signatur, Registrygrößen und semantic-tokens-only nachweisen; Abweichungen werden gezählt und abgelehnt. Themewechsel laden denselben Kontext atomar neu. Bootmanager, Recovery, Diagnose, Dialoge und Menüs nutzen die gemeinsamen Registries produktiv; Bild-/Wortmarke, Nova-Blau und nach rechts gerichteter Kopf bleiben zentral. Hosttests prüfen gültige Übergabe, absichtlich abweichende Modulregistry und Reload. Das GPT/FAT32-Image meldet in EDK2/QEMU VISUAL-CONTINUITY-READY vor dem Countdownframe. Login, Desktop, Shell und Systemanwendungen sind noch nicht implementierte externe Module und können daher den geforderten systemweiten Registry-/Pixelvergleich nicht liefern; außerdem fehlen vollständige BIOS- und Desktop-Parität, SVG-Primäricons und Boot->Login-Handoffverbraucher' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-0011'; Status = 'Teilweise integriert'; Evidence = 'theme.c/ui.c/resources.c: zentrale heapfreie Registry für Dark, Light und High Contrast mit ID, Ressourcen-ID, Name, Autor, Theme-/Ressourcenversion, 22 semantischen Tokens, Zustand und Referenzen. Ein fester 8-Slot-Open-Addressing-Index löst IDs O(1) auf. Aktivierung validiert und lädt das neue Theme vollständig vor dem atomaren Zeigerwechsel, hält exakt eine aktive Referenz, gibt das vorherige Theme danach frei und synchronisiert Farben, Materialfallback sowie Reduced Motion/Animationen ohne Neustart. Hosttests belegen Metadaten, Lookup, Cache ohne Referenzleck, ungültigen Wechsel ohne Zustandsänderung und den Lebenszyklus; OVMF/QEMU meldet THEME-RESOURCE-READY. Externe Themepakete, paketierte Font-/Icon-/Animationsabhängigkeiten, Layoutüberschreibungen und BIOS-Parität bleiben mangels BAP-/Index-Wire-Format in 0002/0003 offen' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-0012'; Status = 'Teilweise integriert'; Evidence = 'resources.c/ui.c: der zentrale heapfreie 128er Cache nutzt denselben 256er Open-Addressing-Index wie der Resource Manager und garantiert damit O(1)-Lookup, Insert und Referenzoperationen ohne Mehrfachkopie. Einträge führen ID, Typ, Adresse, Größe, Referenzen, 64-Bit-Nutzungszeit, saturierende Zugriffshäufigkeit und LRU/LFU/Permanent-Policy. Konfigurierbare Minimum-, Maximum-, Reserve- und Kritischgrenzen werden validiert; Maximalbudget und statischer 512-KiB-Decodepool erzwingen deterministische LRU-vor-LFU-Eviction nach Priorität. Aktive und permanente Ressourcen werden geschützt, Collect bereinigt freigegebene LRU/LFU-Einträge, und Statistiken erfassen Bytes, Hits/Misses, Referenzen, Bereinigungen, Policy-Evictions und Permanent-Skips. Systemfont, 15 Icons und Logo sind produktiv permanent, das aktive Theme bleibt referenziert. Hosttests belegen Grenzen, LRU, LFU, Permanent, Lazy Load, Referenzen, Druck und Collect; OVMF/QEMU meldet RESOURCE-CACHE-READY. Externe BAP-Ressourcen sowie identisches BIOS-Verhalten bleiben durch 0002/0003 und die getrennte BIOS-Runtime offen' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-0013'; Status = 'Teilweise integriert'; Evidence = 'resource_version.c/resources.c/ui.c: zentrale heapfreie 32er Multi-Version-Registry mit 64er Open-Addressing-Index für O(1)-Lookup des aktiven logischen Eintrags. Vollständiges Major.Minor.Patch.Build-Schema, numerische Validierung, Major-Inkompatibilität, abwärtskompatible Minor/Patch-Prüfung und Build-unabhängige Kompatibilität sind implementiert; Build sortiert nur reproduzierbar gleichwertige Kandidaten. Mehrere physische Backing-Ressourcen können derselben logischen ID zugeordnet werden, identische Versionsduplikate werden abgewiesen, Minimum/Maximum-Bereiche wählen deterministisch die höchste Version. Bis zu acht versionierte Mindestabhängigkeiten werden transitiv mit Zyklenschutz geprüft. Auswahl und Rollback sind atomar und stellen bei Konflikt den vorherigen aktiven Stand wieder her. Hosttests belegen Major/Minor/Patch/Build, Bereiche, parallele Versionen, Duplikate, Abhängigkeiten, Konflikt und Rollback; OVMF/QEMU führt Auswahl, Abhängigkeit und Rollback aus und meldet RESOURCE-VERSIONING-READY. Externe Paketmanifeste, manipulierte Manifestbytes und paketübergreifende Versionstabellen bleiben mangels BAP-/Index-Wire-Format in 0002/0003 offen; BIOS-Parität fehlt' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-0014'; Status = 'Teilweise integriert'; Evidence = 'validate-boot-assets.ps1/test-boot-asset-pipeline.ps1/Makefile: automatisierbares Buildzeit-Gate mit Debug/Development/Release-Profilen scannt rekursiv und O(n), sortiert kanonische relative Pfade, erkennt PNG, SVG, TTF, OTF, Theme, Sprache, Animation, Cursor und Binärdaten, weist unbekannte/leere/beschädigte Quellen ab und validiert PNG-Signatur/IHDR/Dimensionen, sicheres SVG-XML ohne DTD, striktes UTF-8 sowie Formatheader. Es erzeugt deterministische boot://-URIs, dieselben FNV-1a-64-IDs wie die Runtime, vollständige Major.Minor.Patch.Build-Versionen, Größen und SHA-256 in einem stabilen Validierungsreport ohne Zeitstempel oder Zufallswerte; ID-Kollisionen brechen den Build ab. asset-pipeline-check erzeugt zweimal byteidentische Reports und beweist einen beschädigten PNG-Fehler. Vollständige Manifest-/Index-/BAP-Erzeugung, Offsets, LZ4/Zstd-Paketkompression und Ed25519/ECDSA-Signierung bleiben ausdrücklich blockiert: 0002/0003 definieren kein Wire-Format und BOOTSECURITY-0001 keinen verwendbaren Schlüssel-/Signaturcontainer. Die Pipeline ist buildzeitlich und besitzt daher keinen QEMU-Laufzeitmarker; das anschließend daraus gebaute UEFI-Image bleibt separat QEMU-getestet' },
    @{ Pattern = 'NPSPEC-KERNELLOADER-0001'; Status = 'Integriert'; Evidence = 'boot2.asm: NKI-bevorzugte Erkennung sowie validiertes direktes ELF32-/ELF64-Laden; QEMU-Positiv- und Negativtests' },
    @{ Pattern = 'NPSPEC-KERNELENTRY-0001'; Status = 'Teilweise integriert'; Evidence = 'boot2.asm und kernel: definierter NBHP/BIB-Registerübergang und frühe Kernelvalidierung; UEFI-Kernelübergang fehlt' },
    @{ Pattern = 'NPSPEC-BOOT-0001-N'; Status = 'Teilweise integriert'; Evidence = 'BIOS Stage 1/2, versioniertes NBHP/BIB, NKI/ELF-Fallback, Fehlerpfade und erster UEFI-Plattformpfad' },
    @{ Pattern = 'NPSPEC-BOOTERROR-0001'; Status = 'Teilweise integriert'; Evidence = 'Einheitlicher Nova-Fehlerbildschirm für Boot- und Kernel-Fehler; vollständige Recovery-Backends fehlen' },
    @{ Pattern = 'NPSPEC-BOOTFS-0001'; Status = 'Teilweise integriert'; Evidence = 'Sektorbasierter read-only Kernelzugriff vorhanden; Dateisystemtreiber-Registry und NovaFS fehlen' },
    @{ Pattern = 'NPSPEC-BOOTGRAPHICS-0001'; Status = 'Teilweise integriert'; Evidence = 'BIOS-Framebuffer-Renderer und UEFI-GOP-Grundpfad; gemeinsame plattformneutrale Runtime fehlt' },
    @{ Pattern = 'NPSPEC-BOOTHANDOFF-0001'; Status = 'Teilweise integriert'; Evidence = 'TLV-basiertes NBHP/BIB wird im BIOS-Pfad aufgebaut und vom Kernel validiert; UEFI-Handoff fehlt' },
    @{ Pattern = 'NPSPEC-BOOTMANAGER-0001'; Status = 'Teilweise integriert'; Evidence = 'BIOS Bootmanager-Runtime, Entries, Auswahl und sichere Fallbacks; persistente Entry-Quellen fehlen' },
    @{ Pattern = 'NPSPEC-BOOTMEMORY-0001'; Status = 'Teilweise integriert'; Evidence = 'Statische Speicherbereiche, Grenzen und lokaler Schreibtest; allgemeine Memory-Map-/Pool-Runtime fehlt' },
    @{ Pattern = 'NPSPEC-BOOTPLATFORM-0001'; Status = 'Teilweise integriert'; Evidence = 'BIOS- und getesteter UEFI-GOP-Einstieg vorhanden; einheitliche Plattform-vtable fehlt' },
    @{ Pattern = 'NPSPEC-BOOTSTAGE1-0001'; Status = 'Integriert'; Evidence = 'boot1.asm: deterministischer 512-Byte-Stage-1-Lader mit Signatur, Fehlerpfad und fester Stage-2-Grenze' },
    @{ Pattern = 'NPSPEC-BOOTSTAGE2-0001'; Status = 'Teilweise integriert'; Evidence = 'boot2.asm: Loader, GUI, Diagnose und Handoff; modulare Ressourcenauslagerung ist durch BAP-Wire-Format blockiert' },
    @{ Pattern = 'NPSPEC-BOOTUI-0002'; Status = 'Teilweise integriert'; Evidence = 'runtime.c/main.c/ui.c: zentraler heapfreier Single-Thread-Runtime-Core mit strikt validierter Subsystemreihenfolge Memory, Platform, Graphics, Diagnostics, Configuration, Resources, Scene, Layout, Motion, Input und Renderer; feste 32er Taskqueue priorisiert Critical, Input, Rendering, Animation, Layout, Background und Idle deterministisch. Jeder produktive UEFI-Frame durchläuft exakt Input, Event Queue, Control, Application, Motion, Layout, Dirty Detection, Render Queue, Rendering, Compositor, Present und Diagnostics; ausgelassene Phasen werden verworfen. Hosttests prüfen Reihenfolge, Scheduler und Fehlerfälle, QEMU belegt Running und abgeschlossene Frames. Eine vollständige gemeinsame BIOS-Runtime, Touch-/Controllerprovider und reale Hardware-Performancezeitmessung fehlen' },
    @{ Pattern = 'NPSPEC-BOOTUI-0003'; Status = 'Teilweise integriert'; Evidence = 'runtime.c/main.c/ui.c: deterministischer Lifecycle Created, Initializing, Loading Resources, Building Scene, Layout, Ready, Running, Suspended, Recovery, Shutdown und Destroyed mit Abweisung ungültiger Transitionen, Eingabesperre in Suspend/Recovery sowie sicherem GUI-Fehlerübergang in Recovery/Textfallback. F6 auf Diagnose testet produktiv Suspend/Resume und zeichnet den Statusframe; Hosttests decken Recovery, Shutdown und Destroy ab, QEMU-Marker und Framebuffer belegen Lifecycle und sichtbaren Endzustand. Echtes Firmware-Suspend/Resume, Hotplug-/Controllerpfade und identische BIOS-Lifecycle-Anbindung fehlen' },
    @{ Pattern = 'NPSPEC-BOOTUI-0004'; Status = 'Teilweise integriert'; Evidence = 'state_model.c/runtime.c/ui.c: gemeinsamer heapfreier 256er Zustandskern für Runtime, Scene, Dialog, Overlay, Control, Focus, Pointer, Keyboard, Touch, Navigation, Page, Animation, Render, Resource, Theme und Error mit domänenspezifischen Übergangsmatrizen, eindeutigem Owner/Parent, atomarer Validierung, OnExit/OnTransition/OnEnter-Eventring, Zeitstempel, Transition-/Fehlerzählern, Checkpoint/Rollback/Reset, Hierarchieprüfung und versioniertem internem Snapshot samt Prüfsumme. Die Runtime nutzt ihn autoritativ; Framephasen werden als Input, Update, Animation, Layout, Render und Present synchronisiert. Hosttests prüfen Scene-Control-Hierarchie, verbotene Sprünge, Press/Release, Rollback, Restore, Korruption und Kind-vor-Eltern-Abbau; F6 und QEMU belegen den produktiven Ablauf samt Statusframe. Bestehende Dialog-, Page-, Navigation-, Motion-, Resource- und Input-Teilautomaten sind noch nicht vollständig auf den gemeinsamen Kern migriert; Touch/Controller und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTUI-0005'; Status = 'Teilweise integriert'; Evidence = 'graphics.c/compositor.c/ui.c und uefi/graphics.c: gemeinsamer validierter GraphicsContext kapselt Width, Height, bytegenauen Pitch, BPP, DPI/Skalierung, PixelFormat, Front-/Backbuffer, Capabilities, Hardwaremetadaten und Diagnose. Rendering, Layout und Controls kennen kein GOP mehr; der Compositor arbeitet ausschließlich offscreen und GAL Present schreibt nur in der Runtime-Present-Phase bounds-geprüft und heapfrei in den sichtbaren Buffer. Konverter decken RGBA/BGRA8888, RGB/BGR888, RGB565 und beliebige Bitmasken ab; GOP RGB/BGR/Bitmask wird validiert, BltOnly abgewiesen. Hosttests prüfen Formatkanäle, Pitch größer als Width, ungültige Buffer und Present-Synchronisation; echter GPT/FAT32-Boot, Recovery und QEMU 800x600/1280x720/1920x1080 belegen den produktiven GOP-Pfad. BIOS/VBE verwendet noch seinen eigenen Renderer; Multi-GOP, Triple Buffer, QHD/4K, echte DPI-Hardwaremetrik und gemessene Zeitbudgets fehlen' },
    @{ Pattern = 'NPSPEC-BOOTUI-0006'; Status = 'Teilweise integriert'; Evidence = 'resolution.c/layout.c/graphics.c/main.c: zentraler gecachter DLU-Scaling-Kontext mit physischem und logischem Viewport, 1920x1080=100-Prozent-Referenz, zuverlässiger DPI- oder Auflösungsheuristik, automatischer und 1000..3000-Promille-Benutzerskalierung, XS/S/M/L/XL/XXL/Ultra-Klassen, 4:3/5:4/16:9/16:10/21:9/32:9/Custom-Erkennung, vierseitiger 3-Prozent-Safe-Area sowie deterministischem DLU-zu-Pixel- und Pixel-zu-DLU-Alignment. Berechnung erfolgt nur bei Start, Auflösungs-, DPI- oder Scalewechsel; Layout, Text, Icons, Radien, Dialoge und Motion-Distanzen verwenden denselben Scale. Hosttests decken 640x480 bis 3840x2160, QHD/UHD, UltraWide, 144 DPI, Override/Fallback und Constraints ab; QEMU belegt 800x600, 1280x720 und die korrigierte 1920x1080-Referenz mit GAL-Present. Sichtbare Scale-Auswahl in Settings, zuverlässige physische GOP-DPI, Multi-/Dual-Screen, BIOS-Parität und QEMU-QHD/UHD fehlen wegen der statischen 1920x1080-Compositorgrenze' },
    @{ Pattern = 'NPSPEC-BOOTUI-0007'; Status = 'Teilweise integriert'; Evidence = 'memory.c/ui.c/diagnostics.c: zentraler heapfreier Manager für Permanent/Runtime/Scene/Animation/Frame/Render/Cache/Diagnostics mit normativen Einzelbudgets und 64-MiB-Gesamtgrenze, getrennten statischen Arenen, O(1)-Bump-Allokation, 16-/64-Byte-Alignment, 256er Objektmetadaten, Owner, Referenzzählung, Pointer-/Double-Free-/Alignment-/Overflow-Erkennung, Peak/Fragmentierung und atomarem Frame-Reset. Der produktive Renderer reserviert und validiert Frame-Metadaten über den Manager; F8 zeigt den geprüften Zustand, Host erzwingt Cache-Overflow mit Safe Mode und QEMU belegt jeden Frame. Bereits ältere statische Subsystempools sind noch nicht vollständig migriert, UEFI-Seitenreservierung und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTUI-0008'; Status = 'Teilweise integriert'; Evidence = 'recovery.c/ui.c/main.c: heapfreier Recovery Manager mit INFO/WARNING/RECOVERABLE/CRITICAL/FATAL, sieben deterministischen Eskalationsstufen, 32er Historie, Diagnoseevents, Feature-Isolation, Safe Mode, Textmodus, Continue-Boot-Invariante und sechs einmalig auslösenden Watchdogs. F10 auf Diagnose simuliert kritische Degradation mit verständlicher Statusmeldung; F9 prüft den fatalen Textfallback mit automatischem Fünf-Sekunden-Weiterstart. Hosttests und QEMU-Marker/Framebuffer belegen beide Pfade. Automatische Hooks für jeden einzelnen Renderer-/Resource-/Layoutfehler, echte GOP-Fehlerinjektion und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTUI-0009'; Status = 'Teilweise integriert'; Evidence = 'configuration.c/input.c/ui.c/main.c: zentraler heapfreier Runtime-Manager mit Version 1.2.0, sicheren Defaults, expliziten Wertebereichen, interner Integritaetspruefsumme, O(1)-Key-Zugriff, atomarem Begin/Set/Commit, vollstaendigem Rollback, Reset, Generation/Benachrichtigung und getrennten temporaeren Overrides. Theme, Reduced Motion, Tooltips, 250..1500-ms-Tooltipverzoegerung, 200..1000-ms-Doppelklickzeit und lineare 25..400-Prozent-Mausgeschwindigkeit sind validierte Werte. 100 Prozent entsprechen jetzt korrekt 1:1 statt der fehlerhaften achtfachen Verlangsamung; Kleinstbewegungen bleiben mindestens ein Pixel. Relative und absolute UEFI-Pointer nutzen dieselbe effektive Konfiguration. Hosttests pruefen 25/100/400 Prozent, Grenzen, Korruption und Transaktionen; GPT/FAT32-QEMU validiert POINTER-SPEED-READY. Das externe Binaerformat bleibt nicht implementierbar definiert: Magic/Formatkennung, Headergroesse, Feldoffsets/Endianness, Section-Typen, externer Pruefsummenalgorithmus und Migrationsabbildungen fehlen; deshalb wird keine inkompatible Persistenz erfunden. Eine Beschleunigungskurve ist ebenfalls nicht normativ festgelegt' },
    @{ Pattern = 'NPSPEC-BOOTUI-0010'; Status = 'Teilweise integriert'; Evidence = 'design.c/ui.c/theme.c/resources.c/icons.c/motion.c: versioniertes Nova-Design-Manifest 1.0.0 mit FNV-Integrität, Major-Kompatibilitätsprüfung sowie gemeinsamen DLU-Tokens für Typografie, Komponenten, Motion, Glass und Schatten. Startvalidierung umfasst Dark/Light/High Contrast, Font, Logo und alle Iconressourcen; OEMs dürfen ausschließlich validierte Bild-/Animationsressourcen und opake Akzentfarben setzen. Hosttests prüfen Tokenwerte, Versionskonflikt, Ressourcen und OEM-Grenzen; QEMU durchläuft alle drei Themes und meldet DESIGN-COMPATIBILITY-READY. Ein nachweisbarer NovaOS-Desktop-Verbraucher, SVG-Primärpfad, externes gemeinsames Design-Token-Paket und vollständige BIOS-Parität fehlen; BAP/Index bleiben durch NPSPEC-BOOTRESOURCE-0002/0003 blockiert' },
    @{ Pattern = 'NPSPEC-BOOTUI-0001'; Status = 'Teilweise integriert'; Evidence = 'architecture.c/runtime.c/ui.c und die gekapselten Subsystemmodule: versioniertes Architekturmanifest für Platform, Resource, Graphics, Renderer, Scene, Layout, Motion, Controls, Navigation, Dialog, Application und Diagnostics mit expliziten Abhängigkeitsmasken, deterministischer Registrierung, Ready-Gate und Startvalidierung. Runtime und State Model erzwingen Lifecycle und Framepipeline; Hosttests weisen ungültige Reihenfolge ab, UEFI/QEMU meldet UI-ARCHITECTURE-READY. BIOS verwendet weiterhin seine platzoptimierte Parallelruntime; Touch, vollständiges Retained-Window-System, SVG/Blur, echte Hardware-Performancewerte und die geforderte Plattformmatrix außerhalb QEMU sind nicht vollständig belegt' },
    @{ Pattern = 'NPSPEC-BOOTUI-'; Status = 'Teilweise integriert'; Evidence = 'BIOS-Runtime mit DLU, Zuständen, Eingabe, Fehlerpfaden und Tokens sowie UEFI-GOP-Grundpfad; gemeinsame Runtime/Pools fehlen' },
    @{ Pattern = 'NPSPEC-BOOTMANAGER-UI-0001'; Status = 'Teilweise integriert'; Evidence = 'BIOS und UEFI: Control-basierte Hauptauswahl, Icons, sichtbarer Fokus, Tastatur/Maus, Statuszeile und sicherer Standardstart; Multi-Boot-Discovery, Touch und vollständiges Informationspanel fehlen' },
    @{ Pattern = 'NPSPEC-BOOTMANAGER-UI-0002'; Status = 'Teilweise integriert'; Evidence = 'boot2.asm: BM_VIEW_DETAILS, F2, Eigenschaften-/Statusansicht und Start-/Erweitert-Aktionen; Motion und Touch fehlen' },
    @{ Pattern = 'NPSPEC-BOOTMANAGER-UI-0003'; Status = 'Teilweise integriert'; Evidence = 'boot2.asm: BM_VIEW_ADVANCED, F3, fokussierbare Startmodusliste, Recovery-/Fallback-Aktionen; Kernelparametereditor fehlt' },
    @{ Pattern = 'NPSPEC-BOOTMANAGER-UI-0004'; Status = 'Teilweise integriert'; Evidence = 'BIOS und UEFI: navigierbares Recovery-Menü, sichere Nicht-verfügbar-Zustände und Rücknavigation; geprüfte schreibende Recovery-Module fehlen' },
    @{ Pattern = 'NPSPEC-BOOTMANAGER-UI-0005'; Status = 'Teilweise integriert'; Evidence = 'boot2.asm: Self-Healing-Systemstatus und sichere Sperre schreibender Reparaturen; NovaFS-Reparaturmodul fehlt' },
    @{ Pattern = 'NPSPEC-BOOTMANAGER-UI-0006'; Status = 'Teilweise integriert'; Evidence = 'boot2.asm: Snapshot-Ansicht mit leerem, erklärtem Zustand; NovaFS-Snapshot-Katalog fehlt' },
    @{ Pattern = 'NPSPEC-BOOTMANAGER-UI-0007'; Status = 'Teilweise integriert'; Evidence = 'boot2.asm: Speichertestansicht, AA55/55AA-Schnelltest, Ergebnis und Fortschritt; vollständiger physischer RAM-Test fehlt' },
    @{ Pattern = 'NPSPEC-BOOTMANAGER-UI-0008'; Status = 'Teilweise integriert'; Evidence = 'boot2.asm: read-only BIOS-Datenträgerstatus; GPT/MBR-, SMART- und Schreibmodule fehlen' },
    @{ Pattern = 'NPSPEC-BOOTMANAGER-UI-0009'; Status = 'Teilweise integriert'; Evidence = 'boot2.asm: Verschlüsselungsstatus und sicher deaktivierte Authentifizierung ohne verschlüsseltes Volume; Crypto-/TPM-Backend fehlt' },
