    @{ Pattern = 'NPSPEC-BOOTRENDER-0001'; Status = 'Teilweise integriert'; Evidence = 'render_queue.c/scene_graph.c/compositor.c/graphics.c/ui.c: plattformneutrale retained UEFI-Renderpipeline über Scene Graph, validierte feste Command Queue, Software-Rasterizer, Offscreen-Compositor und GAL-Present. Der produktive Frame nutzt die Queue für den Hintergrund und traversiert vor jedem Compositing den synchronisierten Control-Szenenbaum; Host und echtes GPT/FAT32-QEMU belegen beide Manager. Vollständige Migration jedes Text-/Icon-/Control-Primitivs auf Commands, PNG/SVG, Pfade/Polygone/Gradienten, Triple Buffer, identischer BIOS-Pfad und gemessene Nanosekundenbudgets fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0002'; Status = 'Teilweise integriert'; Evidence = 'render_queue.c/ui.c: heapfreier 1024er Command Buffer pro Frame mit unveränderlicher Kopie, IDs, Type, Layer, Z, Creation Order, Cliphandle, Opacity, Ressourcenhandle, Ziel-Surface und Geometrie. Validierung verwirft ungültige Commands; stabile Sortierung Layer/Z/Erzeugung, horizontale Rechteck-Batches, verschachtelte Clips, fester Reset und Rasterausführung sind hostgetestet. Der echte UEFI-Frame nutzt Clear als Render Command und QEMU meldet RENDER-COMMANDS-READY. Text, Icons und komplexe Controls erzeugen noch teilweise direkte validierte Rasterizeraufrufe; Transform-/Resource-State-Tabellen und alle spezifizierten Commandtypen fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0003'; Status = 'Teilweise integriert'; Evidence = 'scene_graph.c/controls.c/ui.c: heapfreier retained 256er Szenenpool mit genau einem unsichtbaren Root, stabiler Parent/FirstChild/NextSibling-Hierarchie, Container/Control/Dialog/Graphic/Text/Overlay/Cursor-Typen, Bounds, 16.16-Matrix, Opacity, Visibility/Hidden/Collapsed, Enabled, Layer/Z, Ressourcenhandle und vier Dirtyklassen. Attach/Detach/Destroy verhindern Zyklen, Mehrfacheltern und Elternabbau vor Kindern; lineare Traversierung akkumuliert Transformation, Opacity, Sichtbarkeit und Bounds. Jedes produktive Control wird automatisch registriert und vor jedem UEFI-Frame synchronisiert/traversiert; Host und QEMU belegen den Pfad. Dialog/Page/View-Objekte außerhalb des Control-Pools, Command-Erzeugung ausschließlich aus Traversal, Rotation/Skalierungs-Bounds, Memory-Manager-Allokation und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0004'; Status = 'Teilweise integriert'; Evidence = 'surface_manager.c/layer_manager.c/ui.c/compositor.c: zentraler fester Manager mit 256 generationensicheren Surfaces und 512 generationensicheren Layern, 32er Tiefengrenze, overflow-fester 64-Byte-Pitch-/Größenrechnung, getrennten Persistent/Scene/Effect/Frame/Emergency-Pools, harten Budgets, Recycling, Referenzen, exklusivem Lock/Unlock samt Damage, Frame-Reset und vorreservierter Emergency-Surface. Layer decken alle Standardklassen, stabile Klasse/Z/Creation/ID-Sortierung, Hierarchie/Zyklenschutz, Worldtransform/Opacity/Clip-Vererbung, AUTO/REQUIRED/CACHED/TRANSIENT-Isolation, Surface-Bindung, Parent-Damage und Mutationssperren in Traversal/Compositing/Present ab. Der echte UEFI-Pfad importiert beide Compositorflächen, verwaltet Background/Content/Control/Dialog/Overlay/Cursor/Emergency und QEMU meldet beide Manager bereit. Vollständige Mutation Queue, Masken, Cache-Eviction, Triple Buffer, partielle Present-Regionen, automatische Quality-Degradationskette und gemeinsame BIOS-Anbindung fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0005'; Status = 'Teilweise integriert'; Evidence = 'framebuffer_backend.c/graphics.c/compositor.c und uefi/graphics.c: einheitliches initialisierbares Backend für VBE/GOP/Test/Virtual mit validierter Adresse, Width/Height, bytegenauem Pitch, BPP, Format, Mappinggröße und Capability-Auskunft. Bounds-geprüfte Pixel-Read/Write-, Horizontal-/Vertikallinien-, Rechteck- und kanonische Blockkopier-API berücksichtigt Pitch und RGBA/BGRA/RGB/BGR/RGB565/Bitmask-Konvertierung. Atomare Begin/Damage/Present-Frames mergen bis 32 Regionen und kopieren ausschließlich valide Dirty Regions; der Compositor präsentiert nur noch über das Backend, nicht direkt über GOP/GAL. Diagnose zählt Frames, Presents, Full/Partial, Bytes, Zugriffe und Fehler. Hosttests beweisen fremde Pixel bei Partial Present unverändert sowie Bounds/Pitch; echtes GPT/FAT32-QEMU meldet FRAMEBUFFER-BACKEND-READY und elf GAL-Presents. Der C-Backendvertrag ist im platzkritischen BIOS-Assembler noch nicht angebunden; expliziter Single-Buffer-Modus, Cache-Flush/MMIO-Barrieren, Remote/Virtual-Implementierung und Bare-Metal-Tests fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0006'; Status = 'Teilweise integriert'; Evidence = 'gop_backend.c sowie uefi/graphics.c: getrennte firmwareunabhängig hosttestbare GOP-Policy und dünner UEFI-Adapter. LocateProtocol, bis zu 64 QueryMode-Ergebnisse, Current/Preferred/Fallback-Auswahl, SetMode und vollständige Active-Mode-Neuvalidierung sind deterministisch. Width/Height, PixelsPerScanLine, RGB/BGR/BitMask, disjunkte Farbmasks, FrameBufferBase, FrameBufferSize, Pitch und overflow-feste Mindestgröße werden vor dem gemeinsamen Graphics-/Framebuffer-Backend geprüft; BLT-only wird kontrolliert abgewiesen. Versionierter Descriptor liefert Adresse, Größe, Auflösung, Pitch, BPP, Format, Masks und Modezählung; Diagnose erfasst Kandidaten, Ablehnungen, Auswahlart, Modewechsel und Queries. Hosttests decken Current/Preferred/Fallback/fehlend/BLT-only/Descriptor/Shutdown ab; QEMU belegt normales GPT/FAT32 sowie explizit 800x600, 1280x720 und 1920x1080 mit GOP-MODES-VALIDATED und echten Presents. UEFI-NBHP/BIB-Kernelhandoff des Descriptors, GOP-not-found-Injektion, BitMask-QEMU-Modus und reale Firmware-/Bare-Metal-Matrix fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0007'; Status = 'Teilweise integriert'; Evidence = 'bios/boot2.asm: VBE-2.0-ControllerInfo wird mit VBE2-Signatur angefordert, VESA-Signatur und Version werden geprüft und die untrusted Modusliste wird auf 256 Einträge begrenzt inventarisiert. Die Auswahl folgt deterministisch 1920x1080, 1600x900, 1366x768, 1280x720, 1024x768, 800x600 und danach kompatiblen Modi. Jeder Kandidat sowie der gewählte Modus vor und nach SetMode werden auf supported/graphics/LFB, 32 BPP Direct Color, PhysBasePtr, Width/Height, Pitch, Pitch*Height, Adressüberlauf und exakte BGRX-Masks geprüft. Das BIB erhält Adresse, Pitch, Auflösung, BPP und Format; Fehler löschen Flag und Graphics-Payload und booten im Textmodus weiter. QEMU belegt BACKEND-READY plus Modusrang mit std VGA sowie TEXT-FALLBACK und NOVA_KERNEL_READY mit -vga none. Der gemeinsame C-Framebuffer-Presentvertrag ist noch nicht an den BIOS-Assembler gebunden; explizite Farbmasks und Framebuffergröße passen nicht in den aktuellen BIB-v1.2-Graphics-TLV, RGB888/RGB565 widersprechen der 32-Bit-Voraussetzung und sind nicht aktiviert; Invalid-Mode-Firmwareinjektion und Bare-Metal-Tests fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0008'; Status = 'Teilweise integriert'; Evidence = 'present_scheduler.c/compositor.c: zentraler heapfreier Present Scheduler liegt produktiv zwischen Compositor und Framebuffer Backend. Double Buffer ist Standard; ein optionaler beim Start bereitgestellter dritter Buffer durchläuft Rendering/Ready/Presenting/Displayed. Der globale Lock verhindert paralleles Rendern, 64 Dirty Regions werden validiert und überlappend vereinigt, über 60 Prozent Fläche oder Backendgrenzen erzwingen Full Present. First/Forced/Partial Present, Frame-/Render-/Presentzeiten, VSync-/Pageflip-Capabilities und umfangreiche Diagnose sind typisiert. Ein Presentfehler wird genau einmal als Full Present wiederholt und eskaliert anschließend über den Recovery Manager in Safe Mode, ohne Zustand oder Lock festzuhalten. Hosttests belegen Double/Triple, Zustände, Lock, Merge, Full/Partial, Timing und Recovery; OVMF/QEMU belegt PRESENT-SCHEDULER-READY sowie 15 erfolgreiche Frames. BIOS verwendet weiterhin seinen direkten LFB-Pfad; echtes VSync/Page-Flipping, produktiv aktivierter Triple Buffer, Hardwarezeitmessung und Tearing-/Bare-Metal-Nachweise fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0009'; Status = 'Teilweise integriert'; Evidence = 'dirty_manager.c/compositor.c/present_scheduler.c: zentraler heapfreier Dirty Manager mit konfigurierbarer Kapazität bis 64 und konfigurierbarem Flächenschwellwert. Er verwirft leere/außerhalb liegende Rechtecke, clippt overflow-fest an den Bildschirm, unterdrückt Duplikate, vereinigt transitiv alle Überlappungen und eskaliert Kapazität oder mindestens 50 Prozent Fläche zu typisiertem Full Damage. Blur-, Shadow- und Alpha-Extents erweitern Regionen overflow-fest; Layer-Schnittprüfung und Diagnosen für Add/Merge/Clip/Expansion/Flächen/Full-Gründe sind vorhanden. Der Compositor speist ausschließlich diesen Manager, dessen Damage Set unverändert an den Present Scheduler geht. Hosttests decken Einzel/Mehrfach/Overlap/Duplikat/Clipping/Threshold/Capacity/Effect-Expansion/Overflow ab; QEMU meldet DIRTY-MANAGER-READY und präsentiert weiterhin elf Frames aus dem GPT/FAT32-Image. Controls und Animationen zeichnen produktiv noch überwiegend vollständige Layer neu; Maus-alt/neu ist nicht explizit an den Manager angebunden, BIOS-Parität sowie Performance-/Bare-Metal-Messungen fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0010'; Status = 'Teilweise integriert'; Evidence = 'clip_mask.c/render_queue.c: zentraler heapfreier Clip-/Mask-Manager mit exakt einem Rootclip pro Frame, 32er verschachteltem Stack, 64 unveränderlichen effektiven Scopes, Intersection, Inside/Partial/Outside-Frühklassifikation und Overflow-/Underflowschutz. 64 generationensichere Masken unterstützen Rectangle, 1-Bit-Bitmap, 8-Bit-Alpha, callbackbasierte Vector und Rounded Rectangle; Maskscopes kombinieren beliebig bis Tiefe 32 per Alpha-Multiplikation. Pointer/Stride/Size/Radius/Bounds werden geprüft, aktive/rekursive Masken abgewiesen und ein 256er statischer Coverage-Cache diagnostiziert Hits/Misses. Render Commands erfassen Clip- und Maskscope beim Submit; Clear/Rect/Line/Circle verwerfen unsichtbare Bounds früh, clippen jeden Schreibzugriff und skalieren Quellalpha vor späterem Compositing. Hosttests decken Root/Dialog/Scroll/Nesting, Full/Partial/Outside, alle fünf Masktypen, Kombination, Cache, Recursion, Lifecycle und einen tatsächlich maskierten Rasterpixel ab; QEMU meldet CLIP-MASK-READY und bootet das GPT/FAT32-Image. Direkte ältere Text/Icon/Control-Rasterizer sind noch nicht vollständig auf Commands migriert; Ellipse/Polygon/Bezier, vollständige produktive Dialog-/Scrollmaskbindung, BIOS-Parität und SIMD fehlen. Die zwei contentReference-Platzhalter in der Draft-NPSPEC sind redaktionell ungültig, ändern aber keine technisch auslegbare Anforderung' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0011'; Status = 'Teilweise integriert'; Evidence = 'transform2d.c/scene_graph.c/layer_manager.c/render_queue.c: gemeinsame affine 3x2-API mit Float-Vertrag und deterministischer 16.16-Hotpathdarstellung. Identity, Translation, Rotation im Bogenmaß, Scale, negative Mirror-Skalen, X/Y-Shear, Pivot, Parent*Child, Inverse, Point und Four-Corner-Bounds sind validiert; NaN/Inf, Komponentenlimit, singuläre/overflowende Fixed-Matrizen und Stackfehler werden abgewiesen. Eigene Sin/Cos-Reduktion behandelt Kardinalwinkel ohne libm. Der 32er Transformstack bildet Worldmatrizen; Scene Graph und Layer Manager teilen dieselbe geprüfte Multiplikation und akzeptieren nun 90-Grad-Matrizen. Commands erfassen den aktuellen Transform unveränderlich, transformieren Bounds vor Clip/Mask und rasterisieren Rect/Circle invers sowie Lines über transformierte Endpunkte. Hosttests belegen S->R->T, Pivot, Mirror, Shear, Inverse/Roundtrip, Float->Fixed, Stack, 90-Grad-World-Bounds und ein tatsächlich skaliert/verschobenes Rasterobjekt; QEMU meldet TRANSFORM2D-READY. Alte direkte Text/Icon/Image/Control-Pfade, automatische Old/New-Damage-Anbindung, produktive Rotation/Scale-Animationen, BIOS-Parität, SIMD und echte Mikrosekundenmessungen fehlen. Der contentReference-Platzhalter in der Draft-NPSPEC ist redaktionell ungültig, aber technisch nicht blockierend' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0012'; Status = 'Teilweise integriert'; Evidence = 'image_renderer.c/vector_geometry.c/compositor.c: RGBA8 wird intern premultipliziert verarbeitet, Coverage und Opacity skalieren alle Farbkanäle, Source-over erhält premultiplizierte Ausgaben auch bei teiltransparentem Ziel. Hosttests prüfen den normativen Halbalpha-über-Teilalpha-Fall. Vollständige Vereinheitlichung aller älteren direkten Rasterpfade und BIOS-Pixelparität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0013'; Status = 'Teilweise integriert'; Evidence = 'vector_geometry.c: heapfreier 4096-Segment-Pfad in 16.16-DLU mit Move/Line/Quad/Cubic/Close, deterministischer Kurvenzerlegung, Nonzero/Evenodd-Hit-Test, Vierfach-Kantenglättung und premultipliziertem Fill; dedizierter Runtime-Test und UEFI-Freestanding-Link bestehen. Adaptive Fehlergrenze, Arc, Stroke/Join/Cap, Transformanbindung und produktive SVG-Nutzung fehlen' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0014'; Status = 'Teilweise integriert'; Evidence = 'rounded_geometry.c/controls.c/ui.c/render_queue.c: gemeinsame heapfreie mathematische Rounded-Geometry-API mit uniformen und vier individuellen Radien, automatischem min(width,height)/2-Clamp, 16.16-DLU-Skalierung, Parameter-Lerp, formgenauem Hit Testing, Disabled/2x2/4x4-AA, Inside/Centered/Outside-Rahmen und Diagnosen. Controls und Panels verwenden produktiv denselben AA-Renderer statt separater kantiger Scanline-Helfer. Ein eigener unveränderlicher Render Command rastert Rounded Rectangles invers unter Translation/Rotation/Scale/Mirror und integriert Clip- und Maskscopes. Hosttests decken Radius 0/Maximum/Einzelradien/AA/Scale/Animation/Border/Hit Test/transformiertes Clipping ab; GPT/FAT32 unter OVMF/QEMU meldet ROUNDED-GEOMETRY-READY. Die referenzierte NPSPEC-BOOTRENDER-0013 Gradients fehlt als Datei und 0012 ist falsch befüllt; daher sind Gradient-, Blur- und Shadow-Konturintegration sowie behauptete BIOS-Pixelparität nicht abschließbar' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0015'; Status = 'Teilweise integriert'; Evidence = 'effects.c/rounded_geometry.c/ui.c: gemeinsames heapfreies Achtfach-Effektdatenmodell für Drop/Inner/Ambient/Contact Shadow sowie Outer/Inner/Focus/Accent Glow mit RGBA, Radius, Opacity, negativen/positiven Offsets, stabiler Listenreihenfolge, Clear und Parameter-/Farb-Lerp. Konturen werden direkt aus vier individuellen Rounded-Radien abgeleitet; Low/Standard/High begrenzen den Arbeitsradius deterministisch. Shadow- und Glowphasen sind getrennt, Maskcoverage und harter Clip werden vor jedem boundsgeprüften Pixel angewandt, Damage wird gemeldet, Diagnosen zählen Typen/Pixel/Radius/Qualität. Dialoge verwenden produktiv Ambient plus versetzten Drop Shadow; High Contrast reduziert Effekte. Hosttests decken alle acht Typen, Kapazität, ungültige Werte, Animation, Qualität und echten Alpha-Maskscope plus Clip ab; GPT/FAT32/OVMF meldet SHADOW-GLOW-READY. Ein echter separabler Blur-Kernel, Effektcache, Renderzeitmessung, produktive Focus/Hover-Motion, vollständige Render-Object-Anbindung und BIOS-Pixelparität fehlen; 0012 Alpha ist falsch befüllt und 0013 Gradients fehlt' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0016'; Status = 'Teilweise integriert'; Evidence = 'background_blur.c/ui.c: heapfreier Background-Blur mit getrenntem fertigem Hintergrund-/Ziel-Surface-Vertrag, 512x512-Ergebnis-Cache und 65-Zeilen-Ring statt Render-Hotpath-Allokation, Region-/Surface-/Radiusvalidierung, Box/Gaussian/Dual-Pass-Gaussian, Low/Standard/High und getrennten Horizontal-/Vertikalpässen. In-place-Aufrufe werden kontrolliert abgewiesen. Rounded-4x4-AA und kombinierte Alpha-Masken greifen nach dem Kernel; Damage, überlappungssensitive Invalidierung, Rekursionsschutz, Shutdown und speicherbudgetbedingte Low-Degradation sind typisiert. Hosttests belegen Impulsverteilung, gerundete Kante, Cache Hit/Miss, fremde/überlappende Dirty Regions, Speichermangel und echten Alpha-Maskscope. Nach Reduktion des PE-Images von 40,8 auf 33,7 MiB bootet das reale GPT/FAT32-Image unter OVMF wieder und meldet BACKGROUND-BLUR-READY. Der verlängerte echte Dialogtest belegt Blur-Miss, folgenden Cache-Hit, stabilen Screenshot, Escape, Exit-Motion und Seitenwiederherstellung. Größere Ergebniscaches/Tiling, SIMD, Renderzeitmessung, automatische Layer-Dirty-Generation, BIOS-Pixelparität sowie der fehlende 0012-Alpha-Vertrag bleiben offen' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0017'; Status = 'Teilweise integriert'; Evidence = 'image_renderer.c/branding.c/controls.c: gemeinsamer vorab dekodierender Image Loader und heapfreier Render-Hotpath mit festem 512-KiB-Pixelcache und 240-KiB-Decodebereich. RAW RGBA/BGRA/RGB/RGB565, internes BMP24/32 und PNG 8-Bit Truecolor/RGBA/Indexed einschließlich PLTE/tRNS, CRC, Adler-32, Stored/Fixed/Dynamic Deflate und allen fünf PNG-Filtern werden validiert und in premultiplied RGBA konvertiert; APNG und Interlacing werden definiert abgewiesen. Ressourcen-ID-Cache/Referenzen, Größen-/Stride-/Overflow-/Budgetgrenzen, Nearest/Bilinear, Fit/Fill/Stretch/Original, affine Transformation, Spiegelung, Clip, Mask, Opacity/Tint, Layer-Surface und Damage sind integriert. Das produktive Nova-Logo läuft über diesen Renderer; der Identitätspfad vermeidet Hotpath-Divisionen pro Pixel. Hosttests belegen RAW, Premultiplikation, Cache, Bilinear/Nearest, Mirror/Transform/Clip, BMP, RGBA-/RGB-/Indexed-PNG, Stored/komprimiertes Deflate, CRC- und Interlace-Fehler. OVMF/QEMU meldet IMAGE-RENDERER-READY und durchläuft Menü sowie Dialog/Blur/Escape/Restore. Offen bleiben BAP-Dateiladen wegen BOOTRESOURCE-0002/0003, BIOS-Pixelparität, SIMD, belastbare Decode-/Renderzeitmessung, größere Bild-/Speichermangel-Fuzztests und der normative Alpha-Compositing-Vertrag aus der falsch befüllten 0012' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0018'; Status = 'Teilweise integriert'; Evidence = 'render_quality.c plus diagnostics/ui/controls/branding/effects: zentraler heapfreier Quality Manager mit Ultra, High, Standard, Performance und Safe sowie validierten unveränderlichen Parametertabellen für Blur, Shadow/Glow, AA, Imagefilter, Animation, Transparenz, Dithering, Effektanzahl, Speicherbudget und Compositor-Fallback. Konfiguration schlägt Hardware-Autoauswahl; Safe Mode und Grafikfehler eskalieren kontrolliert. Wechsel invalidieren Blur-Cache, setzen alle angebundenen Subsysteme atomar, erzwingen Full Damage und werden diagnostiziert. Dauerhafte Frameüberschreitung degradiert erst nach drei Messungen, Speichermangel sofort; Entscheidungen liegen außerhalb des Render-Hotpaths. Dialogblur/-shadow/-transparenz, Rounded-AA, Logo-Skalierung, Motion, Effekt-Density und Compositor konsumieren das aktive Profil produktiv. Hosttests decken alle fünf Profile, Invalidwerte, Safe, Hardwarewahl, Hysterese, Speicherdegradation, Cache/Full-Redraw ab. GPT/FAT32/OVMF meldet RENDER-QUALITY-READY und besteht Menü sowie Dialog/Blur/Escape/Restore. Offen bleiben persistentes Konfigurations-Backend, echte GPU-/Firmware-Leistungsinventarisierung, produktives Dithering und Renderauflösung, profilabhängig neu dimensionierte bereits reservierte Pools, Recovery nach Leistungsverbesserung, BIOS-Parität und Bare-Metal-Messungen' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-0019'; Status = 'Teilweise integriert'; Evidence = 'software_renderer.c/ui.c/main.c plus render_queue/clip_mask: gemeinsame heapfreie CPU-Renderer-Lifecycle-API mit Initialize/Shutdown/Begin/Scene-Render/Present/Complete/Reset/Availability und Scalar-SIMD-Referenzpfad. Die produktive UEFI-GUI läuft über Render Commands, Scene Graph, Software-Rasterizer, Compositor und Framebuffer; jeder Frame wird typisiert begonnen und abgeschlossen. Render-/Presentfehler eskalieren deterministisch über Command-/Clip-Abort, Cache Clear und Full Repaint, danach Safe Quality und bei drittem Folgefehler funktionalen UEFI-Textfallback. Speichermangel schaltet Safe, leert Blur und erzwingt Full Damage; doppelter Shutdown, fehlender Framebuffer und ungültige Szenen werden kontrolliert behandelt. Diagnosen erfassen Zustand, Renderer, Frames, Presents, Pixel, Draw Calls, Dirty Regions, Cache, Speicher, Resets, Safe und Text. Hosttests belegen Scene-Traversierung, Erfolg, Memory, vollständige Eskalation und fehlenden Framebuffer. OVMF/QEMU meldet SOFTWARE-RENDERER-READY, bootet Menü/Dialog ohne GPU-API und ein eigener F11-Diagnosetest belegt RESET und RECOVERED mit weiter gezeichneter GUI. BIOS besitzt weiterhin seinen eigenen validierten VBE-LFB-Softwarepfad und Textfallback, nutzt aber noch nicht dieselbe C-Pipeline; Gradienten fehlen mangels 0013-Datei, 0012 Alpha ist falsch befüllt. SIMD-Laufzeitwahl, Reinitialisierung aller persistenten Surface-Pools, identische BIOS-Pixelresultate und Bare-Metal-Fehlerinjektion bleiben offen' },
    @{ Pattern = 'NPSPEC-BOOTRENDER-'; Status = 'Teilweise integriert'; Evidence = 'UEFI: retained Scene Graph, fester Render-Command-Buffer, Rasterizer, Offscreen-Compositor, Dirty Regions und GAL-Present; spezialisierte Detailanforderungen sowie vollständige BIOS-Parität werden je Dokument weiter abgearbeitet' },
    @{ Pattern = 'NPSPEC-BOOTCOMPOSITOR-'; Status = 'Teilweise integriert'; Evidence = 'compositor.c: feste Surface-/Layer-Pools, stabile Z-Sortierung, Alpha, Overlay/Modal, Damage Merge, Glass/Acrylic und Safe-Fallback; BIOS-Anbindung und echter Blur fehlen' },
    @{ Pattern = 'NPSPEC-BOOTMOTION-0007'; Status = 'Teilweise integriert'; Evidence = 'motion.c/navigation.c: zentrale Property-Timeline erzeugt gruppierte Offset-/Opacity-Transitionen, sperrt Fokus, unterstützt Cancel und Reduced Motion; Materialgruppen und BIOS-Anbindung fehlen' },
    @{ Pattern = 'NPSPEC-BOOTMOTION-0009'; Status = 'Teilweise integriert'; Evidence = 'main.c/ui.c/navigation.c: alle UEFI-Menüwechsel laufen über Exit/atomaren Stackwechsel/Enter; Push links, Pop rechts, Recovery/Replace Fade, deterministische Software-Keyframes und QEMU-Transformnachweis; BIOS-Anbindung fehlt' },
    @{ Pattern = 'NPSPEC-BOOTMOTION-0012'; Status = 'Teilweise integriert'; Evidence = 'motion.c/motion.h/ui.c: jede Animation trägt Interruptible, CurrentVelocity 16.16, RemainingDuration und Pausezeit im festen 256er Pool. Interrupt friert Zwischenwert/Geschwindigkeit im selben Frame ein; Resume übernimmt Zwischenwert und Restdauer; Redirect beginnt am aktuellen Wert und berechnet aus erhaltener Geschwindigkeit eine begrenzte neue Dauer; Reverse kehrt ohne Nullannahme zum tatsächlichen Ursprung zurück. Zustände Created/Waiting/Running/Paused/Interrupted/Resuming/Completed/Cancelled, Gruppenpause, Duplicate-Property-Schutz, monotone Timeline, Reduced-Motion-Easing und Safe-Quality bleiben integriert. Diagnosen zählen Interrupt, Pause, Resume, Reverse, Redirect und Fehler. Hosttests prüfen Zwischenwertstabilität, Resume, Geschwindigkeitsumleitung, Rückwärtslauf und Zähler. Ein UEFI-Selbsttest führt Interrupt/Resume/Redirect aus; das GPT/FAT32-Image meldet INTERRUPTIBLE-MOTION-READY vor dem Countdownframe. Beschleunigungsvektoren für echte physikalische Spring-Weiterleitung, rekursive Input-Queue-Unterbrechung, Touch und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTMOTION-0013'; Status = 'Teilweise integriert'; Evidence = 'motion.c/motion.h/theme.c/configuration.c/ui.c/navigation.c: globale heapfreie Motion Policy klassifiziert jede Property O(1) als Allowed, Replaced oder Disabled. Opacity, Tint und Border/Fokus bleiben als ruhige 100-150-ms-Übergänge erhalten; X/Y/Width/Height/Scale/Corner-Radius und weitere räumliche Bewegung werden ersetzt; Blur, Glow und Shadow werden deaktiviert. Spring wird durch Ease Out ersetzt. Ein Policy-Reload wendet die Änderung im selben Frame auf bereits laufende Animationen an, ohne neue Pools; Zähler erfassen Reloads, Ersetzungen, Deaktivierungen und Fehler. Dialoge entfernen Scale, Shadow und Background Blur, Navigation verwendet Cross Fade; Fokus/Fade und bestimmte Progresswerte bleiben funktional. Einstellung und Bootkonfiguration werden atomar persistiert, Theme/High Contrast und Quality Profile kombinieren sich. Hosttests prüfen alle Policyklassen, laufende Spatial/Fade/Blur-Animationen und Unabhängigkeit vom Quality-Pfad. UEFI-Selbsttest meldet REDUCED-MOTION-POLICY-READY; der interaktive EDK2/QEMU-Test schaltet die Einstellung ein, committed sie und weist NAV-REDUCED-FADE bei unveränderter Navigation nach. Indeterminierte Progressamplitude/-frequenz besitzt noch kein eigenes verlangsamtes Reduced-Profil, vollständige BIOS-Parität und die referenzierte fehlende NPSPEC-ACCESSIBILITY-0001 fehlen' },
    @{ Pattern = 'NPSPEC-BOOTMOTION-0014'; Status = 'Teilweise integriert'; Evidence = 'motion.c/motion.h/ui.c: statisches Motion Budget mit 16,667-ms-Frame-, 1-ms-Scheduler- und 512-KiB-Poolgrenze, aktiver Objektzahl, fünf Qualitätsstufen Standard bis Safe sowie typisierten Limits für 256 Animationen, 64 Springs, 64 Material- und 32 Progressanimationen. Allokation wird vor Poolnutzung O(n) deterministisch geprüft; der Scheduler besitzt Rekursionsschutz. Jede Frame-/Schedulerüberschreitung wird gezählt und degradiert exakt in der normativen Reihenfolge Glow, Shadow, Blur, Spring, Material, dekorative Animationen/Safe Mode; essenzielle Opacity/Focus-Policies bleiben erhalten. Reduced Motion deaktiviert seine kostspieligen Kategorien unabhängig/additiv. Hosttests prüfen Speichergrenze, ungültige Typen, sechs Verletzungen, Reihenfolge und Safe Mode. Ein UEFI-Selbsttest simuliert sechs Budgetverletzungen; das GPT/FAT32-Image meldet MOTION-BUDGET-READY vor dem Countdownframe. Property-/Material-/CPU-Zeiten sind im Diagnosemodell vorgesehen, werden aber mangels Firmware-Hochpräzisionstimer noch nicht aus realen Renderphasen gespeist; separate Timeline-/Cachepools, Dauerlastmessung auf physischer Hardware und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTMOTION-'; Status = 'Teilweise integriert'; Evidence = 'motion.c: globale Millisekunden-Timeline, O(n)-Pool-Scheduler, Properties, Easing/Spring-Fallback, Transition/Dialog/Navigation/Fokus/Progress, Unterbrechung, Reduced Motion und Budget-Degradation; BIOS-Anbindung fehlt' },
    @{ Pattern = 'NPSPEC-BOOTRESOURCE-'; Status = 'Teilweise integriert'; Evidence = 'Statisch validierte Font-, Icon- und Logo-Ressourcen; BAP-Loader fehlt' },
    @{ Pattern = 'NPSPEC-BOOTDIAG-0001'; Status = 'Teilweise integriert'; Evidence = 'diagnostics.c/.h und UEFI ui.c/main.c: zentrales heapfreies Diagnoseframework mit elf eingebauten und dynamisch registrierbaren Bereichen, sechs Schweregraden, chronologischen Sequenzen, strukturiertem Modul-/Quellen-/Fehler-/Phasenkontext, konfigurierbarem Ringpuffer, Zeit-/Modul-/Level-/Kategorie-/Phasen-/Fehlerklassenfiltern, kontinuierlichen Frame-/CPU-/GPU-/Speicher-/Cachemetriken, Geheimnisredaktion und nutzerautorisiertem NDF-/JSON-/Text-/Binärexport. Liveanzeige ist standardmäßig aus und nur autorisiert schaltbar; Status garantiert read-only und boot-unabhängig. Übersicht aktualisieren und Ereignisse exportieren sind produktiv an explizite Diagnose-GUI-Aktionen gebunden. Hosttests prüfen Module, Filter, Überlauf, Fehlerkontext, Datenschutz, alle Exporte, Live-Gate und Reset; OVMF/QEMU validiert das Framework vor der vollständigen GUI. Persistentes Exportziel/Dateiauswahl, echte CPU-/GPU-Sensoren, Netzwerk-/Datenträgerbackend, Expertenmodus, vollständiger Tab-/Detailbildschirm nach UI-0014, BIOS-Parität und messbarer Overheadnachweis auf physischer Hardware fehlen' },
    @{ Pattern = 'NPSPEC-BOOTDIAG-0002'; Status = 'Teilweise integriert'; Evidence = 'diagnostics.c/.h, ui.c und bestehende Render-/Compositor-/Dirty-/Layer-/Effect-/Blur-/Image-/Motion-/Resource-/Memory-Diagnosen: vorallokierter 600-Frame-Ring speichert Frame-ID, Start/Ende, Dauer, Draw Calls, Dirty Regions/-Fläche und Layer. Aktuell, letzte Sekunde, letzte zehn Sekunden und Sitzung liefern deterministische FPS, Min/Max/Mittelwert und aggregierte Counts. Laufende Statistiken umfassen Pipelinezeiten einschließlich Idle/Present, Draw Calls, Layer, Rechtecke/Linien, Bilder/Icons, Shadow/Blur, Dirty-Fläche/-Ratio, Resource Cache, Animationen, Speicher/Peak/Pools/Cache und explizite GPU-Verfügbarkeit/Softwarepfad. Nutzergesteuerter NDF-/JSON-/CSV-/Binärexport ist heapfrei; Diagnose-Übersicht zeigt FPS, Framezeit und Draw Calls. Hosttests prüfen 60-/25-FPS-Frames, Sitzung, Speicher, Softwarepfad und alle Exporte; OVMF/QEMU meldet RENDERING-STATISTICS-READY. Glyph-/Font-/SVG-Detailcounter fehlen mangels vollständiger Text-/SVG-Backends, echte GPU-Zeit/Transfer/Speicher mangels GPU-Backend, per-Layer/-Fenster-Zeit und physischer Overhead-/Langzeitnachweis sowie BIOS-Parität bleiben offen' },
    @{ Pattern = 'NPSPEC-BOOTDIAG-0003'; Status = 'Teilweise integriert'; Evidence = 'input.c/.h, ui.c und UEFI main.c: vollstaendig vorallokiertes passives 256er FIFO-Trace mit Rotation fuer Keyboard/Repeat/Pointer/Wheel/DoubleClick/Touch/Controller/System, Fokuswechsel und Shortcuts. Records fuehren Event-/Geraete-/Control-/Fenster-/Dialog-IDs, Flags, Scan/Virtual Key/Modifier/Repeat/Shortcut, maskiertes Unicode, Pointer-/Touchfelder, Queue-Laenge, Capture/Dispatch/Handler/Completion, Latenzen und Renderausloesung. Die produktive Doppelklickerkennung schreibt bei aktiviertem Trace ein eigenes MouseDoubleClick-Record mit Geraet, Pointer, Ziel, Position und Zeit. Filter decken Zeit, Geraet/Typ, Ereignistyp, Control, Fenster, Dialog und Aktionen ab; Queue-Overflow, Duplikat, ungueltiger Fokus, Timeout und Latenzwarnung werden gezaehlt. Tracing und Exporte sind nutzerautorisiert, Secure-Text wird unterdrueckt. Hosttests pruefen Keyboard/Maus, Lifecycle, Filter, Secure-Text, Rotation und vier Exporte; OVMF/QEMU validiert Framework und Doppelklickdetektor. Echte USB-/PS2-Treiberstufen, Key-Up aus UEFI SimpleTextInput, Touchkontakt/Druck, Touchpad/Gamepad-Hardware, reale hochaufloesende Handlerzeit, lueckenlose Aktion-bis-Render-Korrelation, physischer Last-/Overheadtest und BIOS-Paritaet fehlen' },
    @{ Pattern = 'NPSPEC-BOOTDIAG-0004'; Status = 'Teilweise integriert'; Evidence = 'motion.c/.h, diagnostics.c, ui.c und UEFI main.c: vorallokierter passiver 256er Lifecycle-Ring für Started, Paused, Resumed, Repeated, Completed, Cancelled und Failed. Records führen Animation/Target/Parent/Transition/Token, Property, Easing, Zustand, Soll-/Ist-Dauer, Latenzen, Frames, Gruppe, Wiederholung, Priorität, Qualitäts-/Hardwareprofil sowie Frame-, Render-, Compositor-, Layout-, CPU- und explizit nicht verfügbare GPU-Zeit. Frameanalyse zählt Budgetverletzungen, ausgelassene/doppelte Frames und Jitter; Konflikte und Token-Verstöße werden erfasst. Filter decken Typ, Fenster, Dialog, Token, Priorität, Dauer und Fehler ab. Nutzerautorisierter NDF-/JSON-/CSV-/Binärexport ist heapfrei und produktiv an die Ereignisse-Aktion gekoppelt. Hosttests prüfen Lifecycle, Wiederholung, Filter, Jitter, Budget, Export-Gate, vier Formate und Reset; OVMF/QEMU meldet ANIMATION-DIAGNOSTICS-READY. Echte GPU-Zeit, Timeline-/Graph-Detailansicht, allgemeine Window-/Dialog-IDs, physischer Overhead-/Langzeitnachweis, externe Persistenz und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTDIAG-0005'; Status = 'Teilweise integriert'; Evidence = 'resources.c/.h, ui.c und UEFI main.c: vorallokierter passiver 256er Ressourcen-Lifecycle-Ring zeichnet Request, Load Begin, Validate, Decompress, Cache Hit/Miss, Load Complete, Release und Error auf. Records enthalten Ressourcen-/Parent-ID, Typ, Version, Zustand, Ergebnis, Kompression, Trust/Integrität, gepackte/originale Größe, Cache-/Peak-/temporären Speicher, Zeitfelder, Bootphase, Modul und Fehlercode. Status aggregiert Requests, Loads, Prüfungen, Dekompressionen, Hits/Misses, Releases, Fehler, Gesamt-/schnellste-/langsamste Ladezeit und Cacheverbrauch. Filter decken Typ, Ergebnis, Integrität, Zeit, Bootphase, Modul, Cache Hits und Fehler ab. Nutzerautorisierter NDF-/JSON-/CSV-/Binärexport ist heapfrei und in den Diagnoseexport integriert. Hosttests prüfen reale LZ4-Ladung, Wiederverwendung, Integrität, Fehler/Fallback, Filter, Export-Gate, vier Formate und Reset; OVMF/QEMU meldet RESOURCE-LOADING-DIAGNOSTICS-READY. Firmware-Hochpräzisionszeiten pro Loaderphase, allgemeine Parent-/Bootphasen-/Modulzuordnung, SVG-Cache wegen blockiertem SVG-Vertrag, persistenter Export, physischer Overheadnachweis und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTDIAG-'; Status = 'Teilweise integriert'; Evidence = 'diagnostics.c: strukturierter konfigurierbarer Ringpuffer, Schweregrade, Filter, Datenschutz, vier lokale Exportformate, Rendering-/Input-/Motion-/Resource-Snapshots, Frame-/Speicher-/Qualitätsmetriken und QEMU-Initialisierungsnachweis; spezialisierte Diagnosemodule werden je Dokument weiter abgearbeitet' },
    @{ Pattern = 'NPSPEC-BOOTTEST-0003'; Status = 'Teilweise integriert'; Evidence = 'controls.c/.h, input.c/.h, dialog/navigation Testsuites, tests/boot_ui_runtime.c, UEFI main.c und Makefile: isolierte heapfreie 12er Ergebnis-, Summary- und autorisierte Report-API. Button, Toggle Button, Checkbox, List, TextField, Slider, ProgressBar und Scrollbar laufen direkt ueber produktive APIs; Dialog und Navigation binden spezialisierte Suites ein. Validiert werden Lifecycle, Bounds, Accessibility, Focus, Hover/Pressed, Dirty/Visual, Ereignisreihenfolge, Exactly-once, UTF-8, Auswahl, Range/Step, Scrollkopplung sowie Single-/DoubleClick mit Zeit-, Ziel-, Distanz- und TripleClick-Negativfaellen. Radio Button und ComboBox sind ohne produktiven Typ ehrlich SKIPPED. Host prueft 10 PASS/2 SKIPPED; GPT/FAT32-UEFI meldet CONTROL-INTERACTION-TESTS-READY und DOUBLE-CLICK-DETECTION-READY. QEMU-Controltests belegen Settings/List/Icon/Image und Tooltip-Recompose. Tree View, Radio/Combo, Touch, Screenreader, vollstaendige Modifier/Repeatmatrix, Pixelreferenzen aller Zustaende und BIOS-Paritaet fehlen' },
    @{ Pattern = 'NPSPEC-BOOTTEST-0004'; Status = 'Teilweise integriert'; Evidence = 'navigation.c/.h, tests/boot_ui_runtime.c, UEFI main.c, scripts/test-uefi-input.ps1 und Makefile: isolierte heapfreie 10er Routenregistry mit Ergebnis-, Summary- und autorisierter Report-API. Bootmanager, Recovery, Diagnose, Dialog, Liste, Menü, Tastatur und Pointer prüfen über den produktiven Navigation Stack Start, Push, Transition, Zielseite, Selection/Fokus/Scroll/Kontext, Back-Restore, Root-Grenze, Sackgasse und Schleifenindikator; Stack, Visual-/Motion- und Diagnosezustand werden exakt restauriert. Installer und Touch werden ohne Backend ehrlich SKIPPED. Hosttest validiert 8 PASS/2 SKIPPED und Export-Gate. GPT/FAT32-UEFI meldet NAVIGATION-TESTS-READY; der interaktive QEMU-Test belegt reale Unterseiten, Hilfe, Dialoge, Rücksprung, Fokus und Slide/Fade. Produktive Installer-/Touchrouten, Screenreader, Double Click/Gesten/Long Press, echte Zeiten, Screenshots je Route, Self-Healing/Snapshotfachlogik, physische Geräte und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTTEST-0005'; Status = 'Teilweise integriert'; Evidence = 'dialog.c/.h, tests/boot_ui_runtime.c, UEFI main.c, scripts/test-uefi-dialog.ps1 und Makefile: isolierte heapfreie 10er Testregistry mit Ergebnis-, Summary- und autorisierter Report-API für Information, Warning, Error, Confirmation, Progress, Credential, Recovery, Network, Firmware und Custom. Jeder Fall läuft über den produktiven Dialogpfad und prüft Active/Modal, Fokusfalle und Umlauf, Keyboard/Escape, Rückkehrzustand, Progress sowie UTF-8-Credentialeingabe und sichere Löschung; Pool, ID und Diagnosezustand werden exakt restauriert. Hosttest validiert zehn PASS-Fälle und Export-Gate. GPT/FAT32-UEFI führt dieselbe Suite vor der Runtime aus und meldet DIALOG-TESTS-READY; der bestehende QEMU-Dialogtest belegt Enter/Exit-Motion, Blur/Alpha, Fokus, Cancel und Screenshot. Touch/Double-Tap/Long-Press, Screenreader, echte Laufzeitmessung, Referenzbilder aller Typen, alle Theme-/Scale-/Hardwarekombinationen, fachliche Network/Firmware-Backends und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTTEST-0006'; Status = 'Teilweise integriert'; Evidence = 'resolution.c/.h, layout.c, tests/boot_ui_runtime.c, UEFI main.c, scripts/test-uefi-resolution.ps1, scripts/report-uefi-resolutions.ps1 und Makefile: fester heapfreier 80er Ergebnispool; 65 isolierte Kombinationen aus zehn Pflichtauflösungen plus 5:4, 21:9 und 32:9 sowie 100/125/150/175/200 Prozent. Geprüft werden Auflösungs-/Aspect-Klasse, Safe Area, logische DLU-Fläche, Layout/Render, Control-Erreichbarkeit, Dialog/Text und unveränderte Laufzeitkonfiguration. Autorisierter API-Bericht, UEFI-Selbsttestmarker und reale EDK2/QEMU-P6-Framebuffer in 800x600, 1280x720 und 1920x1080 mit validierten Abmessungen und SHA-256-Bericht sind automatisiert. Noch offen: reale GOP-Screenshots aller Pflicht-/Ultra-Wide-/4K-Modi, normative Pixelbaseline/Toleranz und Difference Analyzer, vollständige per-Control-Clipping-/Überlappungs-/Textoverflow-Introspektion, Installer/Self-Healing, SVG/Verläufe, Performancewerte je Matrixfall, alle Themes je Auflösung, physische Hardware und BIOS-Parität' },
    @{ Pattern = 'NPSPEC-BOOTTEST-0007'; Status = 'Teilweise integriert'; Evidence = 'Makefile, scripts/test-firmware-compatibility.ps1 und QEMU: ein gemeinsamer automatisierter Runner baut beide Images, startet Legacy BIOS unter SeaBIOS sowie UEFI unter EDK2/OVMF und erzeugt eine deterministische UTF-8-Kompatibilitätsmatrix. Nachgewiesen werden Firmwareentry, VBE/GOP-Framebuffer, Grafikfallback, Bootmanager, Eingabe, Ressourcen/Integrität, Recovery und BIOS-Kernelhandoff; die Matrix weist pro Fähigkeit BIOS, UEFI, identischen Vertrag und Evidenz aus. BIOS test-platform validiert VBE-Modusranking, Plattformseiten, NBHP/BIB und NOVA_KERNEL_READY; UEFI test-uefi-image validiert GOP, Boot Services/Protocol Discovery, vollständige GUI, Input, Ressourcen, Diagnosen und Fallbacks. Der Bericht markiert ehrlich fehlende Parität: getrennte UI-/Resource-/Input-/Recoverypipelines, fehlender produktiver UEFI-Kernelhandoff/ExitBootServices, Secure Boot/TPM, CSM/Class2/Class3, Memory-Map-Handoff, Touch, Installer, VirtualBox/VMware/Hyper-V, physische Hardware und Pixelidentität' },
    @{ Pattern = 'NPSPEC-BOOTTEST-0008'; Status = 'Teilweise integriert'; Evidence = 'diagnostics.c/.h, tests/boot_ui_runtime.c und UEFI main.c: heapfreier Baseline Manager für Bootzeit, FPS, Framezeit, Speicher, Ressourcenladen, Animation, Eingabelatenz und Cache-Hit-Rate. Baselines führen Build-ID, Version, Hardwareprofil, Firmwaretyp, Richtung und projektspezifische Schwelle. Abweichungen werden ohne Gleitkomma deterministisch in Basispunkten berechnet und an den normativen 5-Prozent- beziehungsweise FPS-3-Prozent-Grenzen als None, Minor, Major oder Critical klassifiziert. Execute liest vorhandene Startup-, Rendering-, Memory-, Resource-, Animation- und Inputdiagnosen; ein autorisierter textueller CI-Bericht enthält Baseline, Messwert, Abweichung und Klasse. Hosttests prüfen exakte Grenzwerte und alle vier Klassen; das reale GPT/FAT32-Image erzeugt einen Bericht und meldet PERFORMANCE-REGRESSION-READY. Persistente Baseline-/Releasehistorie, Diagrammdateien, echter CI-Workflow, Nightly-/PR-Integration, Installer-End-to-End, physische Hardwarematrix und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTTEST-0009'; Status = 'Teilweise integriert'; Evidence = 'resources.c/.h, tests/boot_ui_runtime.c und UEFI main.c: isolierte heapfreie Korruptionssuite mit statischem 64-KiB-Manipulationspuffer und 32er Ergebnisarray. Sie erzeugt reproduzierbar Bitfehler, Truncation, leere Daten, ungültige Header, Signatur, Prüfsumme, Version und Metadaten, führt jede Kopie durch den produktiven Integritäts-/Registrierungspfad und klassifiziert Warning, Recoverable, Critical oder Fatal. Ergebnisse enthalten Ressourcen-/Fallback-ID, Typ, Korruption, Fehlercode, Größen, Speicher vor/nach, Erkennung, Fallback, Bootfortsetzung, unveränderte Quelle, Poolkonsistenz und ob manipulierte Daten verwendet wurden. Hosttests prüfen alle acht Arten, Isolation, Registry-/Cachekonsistenz und autorisierten CI-Bericht; vorhandene Tests decken außerdem PNG-CRC/Header, SHA-256, LZ4-Fehler/Fallback, Fonts, Themes, Animationen und Konfiguration ab. EDK2/QEMU führt acht Proben gegen die produktive Logoressource aus und meldet RESOURCE-CORRUPTION-TESTS-READY. SVG und Asset Packages bleiben durch fehlende Wire-/SVG-Verträge blockiert; echte kryptografische Signaturprüfung, Random-Fuzzing, automatische Recovery-UI je Assettyp, persistente Reports, Installer und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTTEST-0010'; Status = 'Teilweise integriert'; Evidence = 'diagnostics.c/.h, tests/boot_ui_runtime.c und UEFI main.c: gemeinsame heapfreie Fallback-Test-API für Software-/Textausgabe, Standardtheme, Systemschrift, Platzhaltergrafik, Standardanimation, Recovery, Safe Mode, Minimalmodus und Low-End-Profil. Execute nutzt die produktiven Theme-, Font-, Icon-, Animation-, Recovery-, Compositor-, Motion-, Software-Renderer- und Quality-APIs; Resultate führen Modus, Trigger, Fehler/Bootphase, Aktivierungszeit, Speicher vor/nach, Automatic/Activated/Successful, Bedienbarkeit, Integritäts-/Sicherheitserhalt und Recovery-Verfügbarkeit. Doppelte Aktivierungen werden erkannt; ein autorisierter CI-Bericht deckt alle Modi ab. Hosttests aktivieren und validieren alle neun Ketten. EDK2/QEMU führt dieselbe Suite aus, stellt Recovery/Compositor/Motion anschließend kontrolliert wieder her und meldet FALLBACK-MODE-TESTS-READY. GPU-/GOP-/VESA-Ausfälle benötigen weiterhin separate Hardware-/BIOS-Injektion; SVG ist blockiert, Touch/Installer/Self-Healing, gemessene Umschaltzeiten, echte Secure-Boot-Zustandsabfrage und physische Hardwarematrix fehlen' },
    @{ Pattern = 'NPSPEC-BOOTTEST-0001'; Status = 'Teilweise integriert'; Evidence = 'test_architecture.c/.h, tests/boot_ui_runtime.c, UEFI main.c, Makefile und QEMU: zentrale heapfreie 64er Test-Registry und Result-Pool mit stabiler ID, Suite, versionierten Testdaten, Beschreibung, Erwartungswert, Modul, Bootphase, Prioritaet, Hardware-/Qualitaetsprofil, zehn Testebenen und neun Testarten. Der Suite-Runner erfasst Pending/Running/Passed/Failed/Skipped, Fehler, Soll/Ist, Laufzeit, Wiederholungen, Gesamt-/Durchschnittszeit und testweise Zustandsisolation; Duplicate-IDs werden abgewiesen und der Report ist autorisiert. Host prueft PASS/SKIPPED, Reihenfolge, Zeitmetrik, Report-Gate und Erwartungsfehler. GPT/FAT32-UEFI sammelt die zuvor validierten Control-, Navigation-, Dialog- und Rendering-Suites und meldet BOOT-TEST-ARCHITECTURE-READY. Produktive Installer/Self-Healing/Touch/ARM64-Suites, Stackinformationen, persistente CI-/Nightly-/PR-/Release-Artefakte, vollstaendige API-/Zustands-Coverage, physische Stressmatrix und BIOS-Anbindung an denselben Runner fehlen' },
    @{ Pattern = 'NPSPEC-BOOTTEST-0002'; Status = 'Teilweise integriert'; Evidence = 'graphics.c/.h, tests/boot_ui_runtime.c, UEFI main.c, Makefile und bestehende Screenshotskripte: rendererunabhaengiger heapfreier Comparator mit festem 32er Ergebnispool und schreibgeschuetzten versionierten Metadaten fuer ID, Version, Aufloesung, DPI, Theme, Hardwareprofil und Erstellungszeit. RGB/Alpha werden mit +/-1 Kanalwert, Positionen mit +/-1 Pixel und optionaler Maske verglichen; Fehler erzeugen magentafarbene Differenzpixel, erste Fehlerkoordinate, maximale Kanalabweichung, Pixelzahl, Aehnlichkeit und autorisierten Bericht. Host prueft exakt, Farbe, Position, Regression, Maske und Export-Gate. GPT/FAT32-UEFI prueft zwei PASS plus einen absichtlich erkannten FAIL und meldet RENDER-REFERENCE-TESTS-READY. Reale QEMU-Frames bestehen fuer drei Themes, Dialog/Tooltip/Recovery sowie 800x600/1280x720/1920x1080. Ein freigegebener versionierter Vollbild-Baselinebestand und seine automatische Theme-x-Aufloesung-x-Profil-Matrix, persistente Heatmaps/Bereichsbeschreibungen, 1024x768/4K-GOP, SVG/GPU, physische Hardware und BIOS-Paritaet fehlen' },
    @{ Pattern = 'NPSPEC-BOOTTEST-'; Status = 'Teilweise integriert'; Evidence = 'Makefile: BIOS-, Maus-, Theme-, UI-, Recovery-, Plattform-, UEFI-Autostart-, UEFI-Eventqueue/Navigation-, ELF- und Fehlertests' },
    @{ Pattern = 'NPSPEC-BOOTPERF-0001'; Status = 'Teilweise integriert'; Evidence = 'diagnostics.c/diagnostics.h plus Compositor, Dirty Manager, Resource Manager, Controls und Memory Manager: zentrale heapfreie Performance-API liefert FPS, Framezeit, Draw Calls, Dirty Regions, Speicherverbrauch, acht Pipelinezeiten, Min/Max/Mittelwert, Frameklasse und Verletzungen. Separate Startupmetriken validieren UI Engine 30 ms, Theme 10 ms, Ressourcen 20 ms, erstes Fenster 50 ms und ersten Frame 100 ms. Runtime nutzt feste Pools, Double Buffering, zentrale Caches, Dirty Regions und O(1)-Control/Theme-Lookups; Hosttests prüfen Grenzwerte und Metrics Reset. Ein UEFI-Selbsttest prüft Startupgrenzen sowie Klasse A/E und meldet FRAME-BUDGET-READY aus einem GPT/FAT32-Image. Die Startupwerte und Pipeline-Teilzeiten sind noch keine Messungen eines Firmware-Hochpräzisionstimers; der softwaregerenderte QEMU-Debugpfad hält 100 ms/30 FPS real nicht ein. Hardwarebeschleunigung, ARM64/Embedded-/physische Plattformmatrix, Touchlatenz und BIOS-Metrikparität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTPERF-0002'; Status = 'Teilweise integriert'; Evidence = 'diagnostics.c/diagnostics.h sowie UEFI main.c: vollständiges Framebudget für Input 0,5 ms, Events 0,5 ms, Layout 2 ms, Animation 2 ms, Text 1,5 ms, Render 6 ms, Compositor 2 ms und Present 1,5 ms bei 16,667 ms Gesamt. Klassen A bis E, Soft-/Hard-/Phasenverletzungen, Min/Max/Mittelwert und eine Optimierungsaktion je betroffenem Frame werden deterministisch erfasst. Render Quality und Motion Budget erhalten jeden Frame und degradieren automatisch; essenzielle Zustände bleiben erhalten. Der produktive UEFI-Loop pollt Eingaben alle 5 ms, bündelt reine Simple-Pointer-Bewegungen aber auf einen visuellen Frame je 15 ms; Klickflanken, Loslassen und Mausrad bleiben unmittelbar. Hosttests prüfen einen vollständigen Klasse-A-Frame und einen Klasse-E-Frame mit mehreren Teilverletzungen, aber genau einem Framefehler. UEFI-Selbsttest meldet FRAME-BUDGET-READY; Cache und partielle Frames sind in QEMU nachgewiesen. Produktive Frames liefern derzeit konservative feste Teilzeitwerte statt echter Zeitstempel pro Phase; der QEMU-Eingabetest kann Simple-Pointer-Bewegungen nicht zuverlässig synthetisieren, daher ist POINTER-FRAME-COALESCED noch kein automatischer QEMU-Gate. GPU-/Hardwaremessung und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTPERF-0003'; Status = 'Teilweise integriert'; Evidence = 'memory.c/memory.h, resources.c und diagnostics.c: zentrale heapfreie Budget-API mit deterministischen Minimal-/Standard-/Comfort-Profilen 32/64/128 MiB, zehn festen Bereichsbudgets, Gesamt-/Frei-/Peak-/Pool-/Cache-/Fragmentierungsmetriken, Laufzeit-Allokationssperre, sicherer volatile-Zeroisierung, Budgetprüfung, Evictionzähler und fünfstufigem Speicherdruckzustand. Der bestehende Allocator besitzt eine vorreservierte 2176-KiB-Arena, acht begrenzte Pools, 256 feste Objektmetadaten, 16/64-Byte-Ausrichtung, Referenzen, Double-Free-/Overflow-Erkennung und atomaren Frame-Reset. Der Resource Manager meldet reale LRU/LFU-Evictions an das Budget. Hosttests prüfen alle Profile, exakte Bereichssumme, Überlauf, fünf Druckstufen, Runtime-Sperre, Frame-Ausnahme, sichere Löschung und Reset. Das GPT/FAT32-UEFI-Image meldet MEMORY-BUDGET-READY. Noch offen sind die produktive Anbindung jeder spezialisierten Glyph-/SVG-/Theme-/Layout-/Draw-Command-Statik an einzelne Bereichszähler, automatische Ausführung der fünf konkreten Degradationsaktionen, sichere Löschung in künftigen Crypto-/TPM-/Recovery-Consumern, Installer/Recovery-Gesamtlast, physische Low-Memory-Tests und BIOS-Parität' },
    @{ Pattern = 'NPSPEC-BOOTPERF-0004'; Status = 'Teilweise integriert'; Evidence = 'diagnostics.c/diagnostics.h, ui.c und UEFI main.c: zentrale heapfreie Startup-Budget-API überwacht Stage 1/2, Hardware, Grafik, Ressourcen, Theme, UI, Bootmanager, Kernelladen und Handoff mit den normativen 50/150/100/100/80/20/30/50/300/20-ms-Grenzen. Jede Phase führt Start, Ende, Dauer, Budget, Status und Verletzungszahl; Überschreitungen erzeugen Diagnoseereignis und Optimierungshinweis, stoppen den Boot aber nicht. Gesamtziele Standard 1 s, Recovery 2 s, Diagnose 3 s, Hardwareklasse, Performanceklassen A-E, Sicherheitsvorrang und 50-ms-UI-bis-Erstframe sind abfragbar. UEFI misst Entry, Grafik, Ressourcen, Theme, UI, Manager und ersten vollständigen Frame per monotonic TSC; Hosttests prüfen jede exakte Phasengrenze, Überschreitung, Diagnose, Erstframe und Klassen A-E. Das GPT/FAT32-Image meldet STARTUP-BUDGET-READY aus real instrumentierten Phasen. Stage 1 liegt vor Eintritt in die UEFI-App; Kernel/Handoff werden erst im produktiven Loaderpfad messbar. TSC-Frequenz ist per CPUID 0x15/0x16 bestimmt, fällt auf QEMU-kompatible 1-GHz-Schätzung zurück und ist ohne Hardwarekalibrierung kein Referenzzeitnachweis. Kalter/Warm-/Recovery-/Netzwerk-/Installer-/Slow-Disk-End-to-End-Test, echte Parallelisierung, physische Referenzhardware und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTPERF-0005'; Status = 'Teilweise integriert'; Evidence = 'render_quality.c/.h, diagnostics.c, software_renderer.c, ui.c und UEFI main.c: eine zentrale heapfreie AQM-Engine stellt Auto, Ultra, High, Balanced, Low und Safe bereit und bewertet CPU-Score, GPU-Verfügbarkeit/-Last, Software-Renderer, freien Speicher, Framezeit, Cachefüllstand und Auflösung deterministisch. Profile exponieren Blur, Schatten/Glow, Transparenz, Antialiasing, Sampling, SVG-/Glyph-/Icon-Rasteranteil, Animationsschritt, Cachebudget und Compositor-Fallback. Drei langsame Frames sind nötig zur Degradation, 120 stabile schnelle Frames zur schrittweisen Erholung; kurzzeitige Spitzen werden unterdrückt. Wechsel invalidieren Caches, erzwingen genau einen Full Redraw und verändern weder Theme, Layout, Controls, Navigation noch Sicherheitsstatus. Resource Cache wird zwischen Frames gesammelt und, soweit permanente Ressourcen es erlauben, neu begrenzt. Die normative nova_boot_quality-API und vollständige Diagnosetelemetrie sind vorhanden. Unter Einstellungen > Darstellung > Grafikqualität lassen sich alle sechs Modi auswählen und atomar in der Bootkonfiguration speichern. Hosttests prüfen alle Profile, Autoauswahl, Dauerlast, Erholung, Memory/GPU/Software-Fallback, feste Benutzerwahl, ungültige Werte und Parameter. UEFI-Selbsttest meldet ADAPTIVE-QUALITY-READY; ein interaktiver QEMU-Tastaturtest öffnet das neue Untermenü, wählt Safe und weist QUALITY-SELECTION plus CONFIGURATION-COMMIT nach. Echte CPU-/GPU-Auslastungssensoren sind im Firmwarepfad noch nicht angebunden; SVG ist normativ blockiert und Glyph-/SVG-Rasterwerte sind daher nur Policyparameter. Installer/Self-Healing, physische Hardwareprofile und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTPERF-0006'; Status = 'Teilweise integriert'; Evidence = 'render_quality.c/.h, memory.c/.h, resources.c, motion.c, software_renderer.c, dirty/present pipeline, ui.c und UEFI main.c: eigenständige normative LEHP-API erkennt 1 Kern/<=1 GHz, <=32 MiB UI-RAM, fehlende GPU sowie Recovery/Safe und ist zugleich manuell aktivier-/deaktivierbar. Aktivierung koppelt Low (Recovery/Safe: Safe), Software-Renderer, Dirty Regions, Double Buffer, eventgetriebenen Betrieb, 30-FPS-/33,333-ms-Ziel, reduzierte pflichterhaltende Motion, Low Blur, geringe Transparenz, genau eine Schattenebene und aggressiven Cache. Das exakte 32-MiB-Profil weist Resource 6 MiB, Glyph 2 MiB, SVG 2 MiB, Theme 512 KiB, Animation 512 KiB und Controls 2 MiB sowie deterministische Restbudgets aus. Nach UI-Aufbau ist der Runtime-Heap produktiv gesperrt; Frame-Arena bleibt verfügbar. Diagnose exponiert Aktivierung, Auto/Manuell, Softwarepfad, FPS/Framezeit, Speicher/Cache und Erhalt von Layout, Funktion, Sicherheit. Hosttests prüfen starke Hardware ohne Autoaktivierung, Zielhardware, exakte Budgets/Summe, Recovery-Safe, manuelles Ende und Runtime-Sperre. Das reale GPT/FAT32-UEFI-Image aktiviert LEHP auf dem GPU-losen Softwarepfad, zeichnet die vollständige GUI und meldet LOW-END-PROFILE-READY. Die Debug-QEMU-Messung belegt wegen instrumentierter Software-Frames nicht real >=30 FPS oder <=80/150 ms; dafür fehlen optimierter Releasebuild und physische 1-GHz-/512-MiB-Referenzhardware. Touch, echter HDD/USB-I/O-Test, externer SVG/Glyph-Cache, Embedded- und BIOS-End-to-End-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTPERF-0007'; Status = 'Teilweise integriert'; Evidence = 'render_quality.c/.h, memory.c/.h, Resource/Effect/Blur/Motion/Compositor/Software-Renderer und UEFI ui.c: eigenständige normative HQHP-API erkennt >=4 Kerne, >=8 GiB System-RAM, >=256 MiB UI-RAM, gemeldete GPU-Beschleunigung und schnellen Datenträger; manuelle/Policy-Aktivierung ist möglich, aber ohne registriertes GPU-Backend bewusst abgewiesen. Aktivierung koppelt Ultra, 60-FPS-/16,667-ms-Ziel, hochwertige AA/Bilinear-Rasterung, vollständige Motion Tokens, erweiterten Blur, mehrstufige Schatten, Transparenz, Layer-/Resource-Caching, Dirty Regions und Double Buffer. Das exakte 256-MiB-Profil weist Resource 64 MiB, Glyph 16 MiB, SVG 16 MiB, Theme 4 MiB, Animation 16 MiB und Controls 16 MiB plus deterministische Manager-/Reservebudgets aus. Runtime-Heapsperre bleibt über Profilwechsel erhalten; Reduced Motion hat Vorrang. Diagnose exponiert GPU-Backend/-Nutzung/-Last, FPS/Framezeit, Speicher/Cache, Materialien, Fallback und Erhalt von Layout/Funktion/Sicherheit. Hosttests simulieren einen registrierten GPU-Backendvertrag, prüfen Hardwareerkennung, Ultra, exakte Budgets/Summe, 60-FPS-Diagnose, Reduced Motion und GPU-Ausfall mit vollständigem Software-Fallback. QEMU besitzt kein GPU-Backend; das reale GPT/FAT32-Image weist deshalb korrekt HIGH-QUALITY-FALLBACK-READY nach und bootet vollständig im LEHP-Softwarepfad. Echte Hardwarebeschleunigung, GPU-Compositing/Blur/Alpha/Scaling/Vector, >=60 FPS, 4K/UltraWide-GPU-End-to-End, NVMe, Subpixeltext, externer SVG/Glyph-Cache, Touch/Touchpad/Stift, physische Referenzhardware und BIOS-Parität fehlen' },
    @{ Pattern = 'NPSPEC-BOOTPERF-'; Status = 'Teilweise integriert'; Evidence = 'diagnostics.c: 16,67/33,33-ms-Framebudget, Teilzeiten, 32-MiB-Low-End-Speicherbudget, Peak/Cache/Pool, adaptive und feste Qualitätsprofile sowie Safe-Fallback; hardwarebasierte GPU/High-End-Erkennung fehlt' }
)

$rows = foreach ($file in $files) {
    $raw = Get-Content -LiteralPath $file.FullName -Raw -Encoding UTF8
    $relative = $file.FullName.Substring($root.Length + 1).Replace('\', '/')
    $id = [regex]::Match($file.BaseName, 'NPSPEC-[A-Z0-9-]+').Value.TrimEnd('-')
    if ([string]::IsNullOrWhiteSpace($id)) { continue }
    if ([string]::IsNullOrWhiteSpace($raw)) {
        [pscustomobject]@{ Id=$id; File=$relative; Status='Blockiert'; Evidence='Spezifikationsdatei ist leer' }
        continue
    }
    $rule = $evidenceRules | Where-Object { $id -like "$($_.Pattern)*" } | Select-Object -First 1
    if ($rule) {
        [pscustomobject]@{ Id=$id; File=$relative; Status=$rule.Status; Evidence=$rule.Evidence }
    } else {
        [pscustomobject]@{ Id=$id; File=$relative; Status='Prüfung offen'; Evidence='Noch keine explizite Implementierungszuordnung' }
    }
}

$lines = @(
    '# NovaOS Bootmanager NPSPEC-Abdeckung',
    '',
    "Erzeugt: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')",
    '',
    "Dokumente: $($rows.Count)",
    '',
    '| NPSPEC | Status | Implementierungsnachweis | Datei |',
    '|---|---|---|---|'
)
foreach ($row in $rows) {
    $lines += "| $($row.Id) | $($row.Status) | $($row.Evidence) | $($row.File) |"
}

$target = [IO.Path]::GetFullPath((Join-Path (Get-Location) $OutputFile))
$directory = Split-Path -Parent $target
if (-not (Test-Path -LiteralPath $directory)) { New-Item -ItemType Directory -Path $directory | Out-Null }
[IO.File]::WriteAllLines($target, $lines, [Text.UTF8Encoding]::new($false))

$rows | Group-Object Status | Sort-Object Name | ForEach-Object {
    Write-Host ("{0}: {1}" -f $_.Name, $_.Count)
}
Write-Host "Abdeckungsmatrix: $target"
